1	import { useCallback, useEffect, useState } from "react";
2	import SidebarLayout from "@/components/SidebarLayout";
3	import { useAuth } from "@/hooks/useAuth";
4	import { supabase } from "@/integrations/supabase/client";
5	import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
6	import { Badge } from "@/components/ui/badge";
7	import { Separator } from "@/components/ui/separator";
8	import { Skeleton } from "@/components/ui/skeleton";
9	import { Mail, Calendar, Briefcase, FileText, Zap, Crown } from "lucide-react";
10	import { FadeIn } from "@/components/ui/fade-in";
11	import { StaggerList } from "@/components/ui/stagger-list";
12	import { toast } from "sonner";
13	
14	function getInitials(email?: string | null): string {
15	  if (!email) return "?";
16	  const name = email.split("@")[0];
17	  const parts = name.split(/[._-]/);
18	  if (parts.length >= 2) return (parts[0][0] + parts[1][0]).toUpperCase();
19	  return name[0]?.toUpperCase() || "?";
20	}
21	
22	function getUserName(email?: string | null): string {
23	  if (!email) return "User";
24	  return email.split("@")[0].replace(/[._-]/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
25	}
26	
27	const Profile = () => {
28	  const { user, profile } = useAuth();
29	  const plan = profile?.plan ?? "free";
30	  const isPaid = plan !== "free";
31	
32	  // Fetch usage stats
33	  const [stats, setStats] = useState<{ totalJobs: number; totalResumes: number; creditsUsed: number } | null>(null);
34	  const fetchStats = useCallback(async () => {
35	    if (!user) return;
36	    try {
37	      const [jobsRes, usageRes] = await Promise.all([
38	        supabase.from("jobs").select("id, resumes(count)").eq("user_id", user.id),
39	        supabase.from("usage_logs").select("credits_used").eq("user_id", user.id),
40	      ]);
41	      const jobs = jobsRes.data ?? [];
42	      const totalJobs = jobs.length;
43	      const totalResumes = jobs.reduce((sum: number, j: any) => sum + (j.resumes?.[0]?.count ?? 0), 0);
44	      const creditsUsed = (usageRes.data ?? []).reduce((sum: number, u: any) => sum + (u.credits_used ?? 0), 0);
45	      setStats({ totalJobs, totalResumes, creditsUsed });
46	    } catch {
47	      toast.error("Failed to load activity stats");
48	    }
49	  }, [user]);
50	  useEffect(() => { fetchStats(); }, [fetchStats]);
51	
52	  // Credits
53	  const sub = profile?.subscription_credits ?? 0;
54	  const top = profile?.topup_credits ?? 0;
55	  const bonus = profile?.bonus_credits ?? 0;
56	  const split = sub + top + bonus;
57	  const totalCredits = split > 0 ? split : (profile?.credits ?? 0);
58	
59	  return (
60	    <SidebarLayout>
61	      <main className="w-full max-w-[700px] mx-auto px-4 sm:px-6 lg:px-8 py-8">
62	        <FadeIn>
63	          <h1 className="text-xl font-semibold text-foreground tracking-tight mb-6">Profile</h1>
64	        </FadeIn>
65	        <StaggerList className="space-y-6" stagger={0.08}>
66	          {/* Account card */}
67	          <Card>
68	            <CardContent className="p-6">
69	              <div className="flex items-center gap-4">
70	                <div className="h-14 w-14 rounded-full bg-primary text-primary-foreground text-lg font-bold flex items-center justify-center shrink-0">
71	                  {getInitials(user?.email)}
72	                </div>
73	                <div className="min-w-0 flex-1">
74	                  <h2 className="text-lg font-semibold text-foreground truncate">{getUserName(user?.email)}</h2>
75	                  <p className="text-sm text-muted-foreground truncate">{user?.email}</p>
76	                  <div className="flex items-center gap-2 mt-1.5">
77	                    <Badge variant={isPaid ? "default" : "secondary"} className="text-xs capitalize gap-1">
78	                      {isPaid && <Crown className="h-3 w-3" />}
79	                      {plan} plan
