import {
  Briefcase,
  Home,
  Settings,
  CreditCard,
  Users,
  CheckSquare,
  Globe,
  Layers,
  Sparkles,
} from "lucide-react";
import {
  Sidebar,
  SidebarContent,
  SidebarFooter,
  SidebarHeader,
  SidebarGroup,
  SidebarGroupLabel,
  SidebarGroupContent,
  SidebarMenu,
  SidebarMenuItem,
  SidebarMenuButton,
  SidebarSeparator,
} from "@/components/ui/sidebar";
import { useNavigate, useLocation } from "react-router-dom";

interface JobSidebarProps {
  showDashboard?: boolean;
  showMyJobs?: boolean;
  onNewJob?: () => void;
  onDashboard?: () => void;
  onMyJobs?: () => void;
  onAuthRequired?: () => void;
  isAuthenticated?: boolean;
  selectedJobId?: string | null;
}

const JobSidebar = ({
  showDashboard,
  showMyJobs,
  onDashboard,
  onMyJobs,
  isAuthenticated = true,
}: JobSidebarProps) => {
  const navigate = useNavigate();
  const { pathname } = useLocation();

  const workspaceItems = [
    {
      icon: Home,
      label: "Dashboard",
      isActive: !!showDashboard,
      onClick: onDashboard,
      show: isAuthenticated && !!onDashboard,
    },
    {
      icon: Briefcase,
      label: "My Jobs",
      isActive: !!showMyJobs,
      onClick: onMyJobs,
      show: isAuthenticated && !!onMyJobs,
    },
    {
      icon: CheckSquare,
      label: "Tasks",
      isActive: pathname === "/tasks",
      onClick: () => navigate("/tasks"),
      show: isAuthenticated,
    },
  ];

  const accountItems = [
    {
      icon: CreditCard,
      label: "Billing",
      isActive: pathname === "/billing",
      onClick: () => navigate("/billing"),
    },
    {
      icon: Settings,
      label: "Settings",
      isActive: pathname === "/settings",
      onClick: () => navigate("/settings"),
    },
    {
      icon: Users,
      label: "Team",
      isActive: pathname === "/team",
      onClick: () => navigate("/team"),
    },
    {
      icon: Globe,
      label: "Career Page",
      isActive: pathname === "/career-settings",
      onClick: () => navigate("/career-settings"),
    },
  ];

  return (
    <Sidebar collapsible="offcanvas" className="border-r border-sidebar-border">
      {/* ── Brand ── */}
      <SidebarHeader className="px-4 py-4">
        <button
          onClick={onDashboard}
          className="flex items-center gap-2.5 outline-none focus-visible:ring-2 focus-visible:ring-ring rounded-md"
        >
          <div className="h-7 w-7 rounded-lg bg-primary flex items-center justify-center shrink-0">
            <Layers className="h-4 w-4 text-primary-foreground" />
          </div>
          <span className="font-bold text-foreground tracking-tight text-base">
            Rankora
          </span>
        </button>
      </SidebarHeader>

      <SidebarSeparator />

      {/* ── Nav ── */}
      <SidebarContent className="px-2 py-3 gap-0">
        {/* Workspace */}
        <SidebarGroup className="p-0">
          <SidebarGroupLabel className="px-2 mb-1 text-[10px] font-semibold uppercase tracking-widest text-muted-foreground/50">
            Workspace
          </SidebarGroupLabel>
          <SidebarGroupContent>
            <SidebarMenu>
              {workspaceItems
                .filter((item) => item.show)
                .map(({ icon: Icon, label, isActive, onClick }) => (
                  <SidebarMenuItem key={label}>
                    <SidebarMenuButton
                      isActive={isActive}
                      onClick={onClick}
                      className="h-9 gap-3 rounded-lg text-sm"
                    >
                      <Icon className="h-4 w-4 shrink-0" />
                      <span>{label}</span>
                    </SidebarMenuButton>
                  </SidebarMenuItem>
                ))}
            </SidebarMenu>
          </SidebarGroupContent>
        </SidebarGroup>

        {/* Account */}
        {isAuthenticated && (
          <SidebarGroup className="p-0 mt-5">
            <SidebarGroupLabel className="px-2 mb-1 text-[10px] font-semibold uppercase tracking-widest text-muted-foreground/50">
              Account
            </SidebarGroupLabel>
            <SidebarGroupContent>
              <SidebarMenu>
                {accountItems.map(({ icon: Icon, label, isActive, onClick }) => (
                  <SidebarMenuItem key={label}>
                    <SidebarMenuButton
                      isActive={isActive}
                      onClick={onClick}
                      className="h-9 gap-3 rounded-lg text-sm"
                    >
                      <Icon className="h-4 w-4 shrink-0" />
                      <span>{label}</span>
                    </SidebarMenuButton>
                  </SidebarMenuItem>
                ))}
              </SidebarMenu>
            </SidebarGroupContent>
          </SidebarGroup>
        )}
      </SidebarContent>

      {/* ── Footer ── */}
      <SidebarFooter className="px-3 pb-4 pt-2">
        <SidebarSeparator className="mb-3" />
        <div className="rounded-xl border border-sidebar-border bg-sidebar-accent/40 p-3 space-y-2.5">
          <div className="flex items-center gap-2">
            <Sparkles className="h-3.5 w-3.5 text-sidebar-primary" />
            <span className="text-xs font-semibold text-sidebar-foreground">
              What's new
            </span>
          </div>
          <div className="flex gap-2">
            <a
              href="/request-feature"
              className="flex-1 text-center text-xs font-medium py-1.5 rounded-lg border border-sidebar-border bg-background/60 text-sidebar-foreground hover:bg-sidebar-accent transition-colors duration-150"
            >
              Feature Request
            </a>
            <a
              href="/changelog"
              className="flex-1 text-center text-xs font-medium py-1.5 rounded-lg border border-sidebar-border bg-background/60 text-sidebar-foreground hover:bg-sidebar-accent transition-colors duration-150"
            >
              Changelog
            </a>
          </div>
        </div>
      </SidebarFooter>
    </Sidebar>
  );
};

export default JobSidebar;

