1	import React, { useState } from "react";
2	import { useAuth } from "@/hooks/useAuth";
3	import { useTheme } from "next-themes";
4	import { useNavigate } from "react-router-dom";
5	import { Button } from "@/components/ui/button";
6	import {
7	  DropdownMenu,
8	  DropdownMenuContent,
9	  DropdownMenuItem,
10	  DropdownMenuSeparator,
11	  DropdownMenuTrigger,
12	} from "@/components/ui/dropdown-menu";
13	import {
14	  LogOut, ShieldCheck,
15	  Sun, Moon, Monitor,
16	  User, CalendarCheck,
17	} from "lucide-react";
18	import AuthDialog from "@/components/AuthDialog";
19	import WalletDropdown from "@/components/WalletDropdown";
20	import NotificationBell from "@/components/NotificationBell";
21	
22	function getInitials(email?: string | null): string {
23	  if (!email) return "?";
24	  const name = email.split("@")[0];
25	  const parts = name.split(/[._-]/);
26	  if (parts.length >= 2) return (parts[0][0] + parts[1][0]).toUpperCase();
27	  return name[0]?.toUpperCase() || "?";
28	}
29	
30	function getUserName(email?: string | null): string {
31	  if (!email) return "User";
32	  const name = email.split("@")[0];
33	  return name.replace(/[._-]/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
34	}
35	
36	const AppHeader = () => {
