                      <Route path="/changelog" element={<Changelog />} />
                      <Route path="/payment/callback" element={<PaymentCallback />} />
                      <Route path="*" element={<NotFound />} />
                    </Routes>
                  </MaintenanceGate>
                } />
              </Routes>
            </Suspense>
            <ChatWidget />
          </BrowserRouter>
        </TooltipProvider>
      </AuthProvider>
    </ThemeProvider>
  </QueryClientProvider>
);

export default App;

