import { motion } from "framer-motion";
import { Children, type ReactNode } from "react";

interface StaggerListProps {
  children: ReactNode;
  stagger?: number;
  duration?: number;
  direction?: "up" | "down" | "left" | "right" | "none";
  distance?: number;
  className?: string;
}

const directionMap = {
  up: { y: 1, x: 0 },
  down: { y: -1, x: 0 },
  left: { x: 1, y: 0 },
  right: { x: -1, y: 0 },
  none: { x: 0, y: 0 },
};

const StaggerList = ({
  children,
  stagger = 0.05,
  duration = 0.25,
  direction = "up",
  distance = 10,
  className,
}: StaggerListProps) => {
  const dir = directionMap[direction];

  return (
    <motion.div
      className={className}
      initial="hidden"
      animate="visible"
      variants={{ hidden: {}, visible: { transition: { staggerChildren: stagger } } }}
    >
      {Children.map(children, (child) =>
        child ? (
          <motion.div
            variants={{
              hidden: { opacity: 0, x: dir.x * distance, y: dir.y * distance },
              visible: { opacity: 1, x: 0, y: 0, transition: { duration, ease: "easeOut" } },
            }}
          >
            {child}
          </motion.div>
        ) : null
      )}
    </motion.div>
  );
};

export { StaggerList };

