          <AccountInfoCard showHero={false} />
          <PaymentHistoryCard />
          <UsageHistoryCard />
        </StaggerList>
      </main>
    </SidebarLayout>
  );
};

export default Billing;

toolUseResult.originalFile:
# Fix: Eliminate Loading Flashes on Page Navigation

## Context
Every page switch in Rankora shows a loading skeleton (PageLoader), making the app feel sluggish. Users see loading flashes even when navigating between pages they've already visited. Root causes: all 17 routes are lazy-loaded with Suspense, QueryClient has no caching defaults, and core pages use raw Supabase calls with no cache.

---

## Phase 1: QueryClient Global Defaults (Biggest Win)

**File:** `src/App.tsx` line 33

Replace `new QueryClient()` with:
```typescript
const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      staleTime: 5 * 60 * 1000,
      gcTime: 10 * 60 * 1000,
      refetchOnWindowFocus: false,
      refetchOnMount: false,
      retry: 1,
    },
  },
});
```

**Why:** staleTime=0 (current default) means every React Query hook refetches on mount. Pages with React Query (Team, Tasks, Career, Billing sub-components, Admin tabs) all show loading spinners on every revisit. Setting staleTime=5min keeps data fresh during navigation. Queries that already set their own staleTime (useFeatureFlags 60s, useTasks 30s, useTeam 60s) override this automatically.

---

## Phase 2: Eager Import Core Pages

**File:** `src/App.tsx` lines 15-31

Change to eager imports for pages users navigate between constantly:
```typescript
// Eager imports — core pages (no Suspense flash)
import Index from "./pages/Index";
import Auth from "./pages/Auth";
import Settings from "./pages/Settings";
import Profile from "./pages/Profile";
import Billing from "./pages/Billing";
import Team from "./pages/Team";
import Tasks from "./pages/Tasks";

// Keep lazy — infrequent or large pages
const Admin = lazy(() => import("./pages/Admin"));        // 267KB, admin-only
const NotFound = lazy(() => import("./pages/NotFound"));
const PaymentCallback = lazy(() => import("./pages/PaymentCallback"));
const BookDemo = lazy(() => import("./pages/BookDemo"));
const RequestFeature = lazy(() => import("./pages/RequestFeature"));
const Changelog = lazy(() => import("./pages/Changelog"));
const Apply = lazy(() => import("./pages/Apply"));
const CareerPage = lazy(() => import("./pages/CareerPage"));
const CareerSettings = lazy(() => import("./pages/CareerSettings"));
const LandingPage = lazy(() => import("@/components/LandingPage"));
```

**Why:** Lazy-loaded chunks trigger the `<Suspense fallback={<PageLoader />}>` on every first visit. Core pages (Index, Settings, Profile, Billing, Team, Tasks, Auth) are small (5-28KB each, except Index at ~127KB) and share most imports through existing manualChunks in vite.config. Users visit these pages 100% of the time — we're just front-loading an inevitable cost.

Keep `<Suspense>` wrapper for remaining lazy pages.

---

## Phase 3: Convert Index.tsx fetchPastJobs to React Query

**File:** `src/pages/Index.tsx`

Replace the `useState`/`useEffect`/`useCallback` pattern for `pastJobs` with `useQuery`:
```typescript
const { data: pastJobs = [], isLoading: loadingPastJobs, refetch: refetchPastJobs } = useQuery({
  queryKey: ["pastJobs", user?.id],
  queryFn: async () => { /* existing fetch logic */ },
  enabled: !!user,
  staleTime: 2 * 60 * 1000,
});
```

Replace all `fetchPastJobs()` calls with `refetchPastJobs()`. Remove the old state variables, useCallback, and useEffect.

**Why:** Index is the most-visited page. Currently uses raw Supabase with zero cache — refetches the entire job list on every navigation to "/jobs" or "/".

---

## Phase 4: Convert Profile.tsx fetchStats to React Query

**File:** `src/pages/Profile.tsx`

Same pattern — replace `useState`/`useEffect` with `useQuery`:
```typescript
const { data: stats } = useQuery({
  queryKey: ["profileStats", user?.id],
  queryFn: async () => { /* existing Promise.all fetch */ },
  enabled: !!user,
  staleTime: 5 * 60 * 1000,
});
```

**Why:** Profile page fetches 3 queries (jobs, resumes count, usage logs) on every mount with loading skeleton. Caching eliminates the flash on revisit.

---

## Files to Modify
1. `src/App.tsx` — QueryClient defaults + eager imports (Phase 1 & 2)
2. `src/pages/Index.tsx` — Convert fetchPastJobs to useQuery (Phase 3)
3. `src/pages/Profile.tsx` — Convert fetchStats to useQuery (Phase 4)

## No Changes Needed
- `src/components/ProtectedRoute.tsx` — auth `loading` is only `true` on initial boot, not during navigation (confirmed)
- `src/hooks/useAuth.tsx` — loading behavior is correct

## Verification
1. `npm run build` — confirm no type errors and check bundle size delta
2. Manual test: navigate between Jobs → Profile → Settings → Team → Tasks → Billing rapidly — no loading skeletons should appear after initial load
3. Navigate away and back to Jobs page — job list should appear instantly from cache
4. Create a new job, verify the list updates (invalidation still works)

