1	import { useState } from "react";
2	import { Activity as ActivityIcon, Loader2 } from "lucide-react";
3	import SidebarLayout from "@/components/SidebarLayout";
4	import { FadeIn } from "@/components/ui/fade-in";
5	import { StaggerList } from "@/components/ui/stagger-list";
6	import { Card, CardContent } from "@/components/ui/card";
7	import { Button } from "@/components/ui/button";
8	import { Skeleton } from "@/components/ui/skeleton";
9	import ActivityItem from "@/components/ActivityItem";
10	import { useActivityFeed } from "@/hooks/useActivityFeed";
11	import { useTeam } from "@/hooks/useTeam";
12	
13	// ─── Filter tabs ──────────────────────────────────────────────────────────────
14	
15	const FILTERS = ["All", "Tasks", "Notes", "Stages", "Applications", "Members"] as const;
16	type Filter = (typeof FILTERS)[number];
17	
18	// ─── Skeletons ────────────────────────────────────────────────────────────────
19	
20	function ActivitySkeleton() {
21	  return (
22	    <div className="space-y-3 p-4">
23	      {[1, 2, 3, 4].map((i) => (
24	        <div key={i} className="flex items-center gap-3">
25	          <Skeleton className="h-8 w-8 rounded-full shrink-0" />
26	          <Skeleton className="h-12 flex-1 rounded-lg" />
27	        </div>
28	      ))}
29	    </div>
30	  );
31	}
32	
33	// ─── Main page ────────────────────────────────────────────────────────────────
34	
35	const Activity = () => {
36	  const { team, isLoading: teamLoading } = useTeam();
37	  const teamId = team?.id ?? null;
38	
39	  const [activeFilter, setActiveFilter] = useState<Filter>("All");
40	
41	  const { activities, isLoading, isFetching, hasMore, loadMore } =
42	    useActivityFeed(teamId, activeFilter);
43	
44	  const showLoading = isLoading || (teamLoading && !teamId);
45	
46	  return (
47	    <SidebarLayout>
48	      <main className="w-full max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
49	        {/* Header */}
50	        <FadeIn>
51	          <h1 className="text-2xl font-bold text-foreground mb-1">Activity</h1>
52	          <p className="text-sm text-muted-foreground mb-5">
53	            See what your team has been up to.
54	          </p>
55	
56	          {/* Filter tabs */}
57	          <div className="flex flex-wrap gap-1.5 mb-5">
58	            {FILTERS.map((f) => (
59	              <button
60	                key={f}
61	                onClick={() => setActiveFilter(f)}
62	                className={
63	                  activeFilter === f
64	                    ? "px-3 h-7 rounded-full text-xs font-semibold bg-primary text-primary-foreground transition-colors"
65	                    : "px-3 h-7 rounded-full text-xs font-medium text-muted-foreground hover:text-foreground hover:bg-muted/60 transition-colors"
66	                }
67	              >
68	                {f}
69	              </button>
70	            ))}
71	          </div>
72	        </FadeIn>
73	
74	        {/* No team state */}
75	        {!teamLoading && !teamId && (
76	          <div className="flex flex-col items-center justify-center py-16 space-y-4 text-center">
77	            <div className="rounded-xl bg-muted/50 p-4">
78	              <ActivityIcon className="h-7 w-7 text-muted-foreground/50" />
79	            </div>
80	            <div className="space-y-1">
81	              <p className="text-sm font-medium">No team yet</p>
82	              <p className="text-sm text-muted-foreground max-w-xs">
83	                Create or join a team to see activity here.
84	              </p>
85	            </div>
86	          </div>
87	        )}
88	
89	        {/* Loading skeleton */}
90	        {showLoading && (
91	          <Card className="border border-border/60 shadow-sm">
92	            <ActivitySkeleton />
93	          </Card>
94	        )}
95	
96	        {/* Empty state */}
97	        {!showLoading && teamId && activities.length === 0 && (
98	          <div className="flex flex-col items-center justify-center py-16 space-y-4 text-center">
99	            <div className="rounded-xl bg-muted/50 p-4">
100	              <ActivityIcon className="h-7 w-7 text-muted-foreground/50" />
101	            </div>
102	            <div className="space-y-1">
103	              <p className="text-sm font-medium">No activity yet</p>
104	              <p className="text-sm text-muted-foreground max-w-xs">
105	                Activity from your team will appear here as things happen.
106	              </p>
107	            </div>
108	          </div>
109	        )}
110	
111	        {/* Activity list */}
112	        {!showLoading && teamId && activities.length > 0 && (
113	          <StaggerList className="space-y-0" stagger={0.04}>
114	            <Card className="border border-border/60 shadow-sm">
115	              <CardContent className="p-0">
116	                <div className="divide-y divide-border/50">
117	                  {activities.map((activity) => (
118	                    <div key={activity.id} className="px-4">
119	                      <ActivityItem activity={activity} compact={false} />
120	                    </div>
121	                  ))}
122	                </div>
123	
124	                {/* Load more */}
125	                {hasMore && (
126	                  <div className="flex justify-center px-4 py-3 border-t border-border/50">
127	                    <Button
128	                      variant="ghost"
129	                      size="sm"
130	                      onClick={loadMore}
131	                      disabled={isFetching}
132	                      className="text-xs text-muted-foreground"
133	                    >
134	                      {isFetching ? (
135	                        <Loader2 className="h-3.5 w-3.5 animate-spin mr-1.5" />
136	                      ) : null}
137	                      Load more
138	                    </Button>
139	                  </div>
140	                )}
141	              </CardContent>
142	            </Card>
143	          </StaggerList>
144	        )}
145	      </main>
146	    </SidebarLayout>
147	  );
