import { useState, useEffect, useRef, useCallback } from "react";
import { toast } from "sonner";
import { Globe, Copy, ExternalLink, Loader2, Save, Eye } from "lucide-react";
import SidebarLayout from "@/components/SidebarLayout";
import { FadeIn } from "@/components/ui/fade-in";
import { StaggerList } from "@/components/ui/stagger-list";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import { useTeam } from "@/hooks/useTeam";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface CareerPageConfig {
  id: string;
  team_id: string;
  company_name: string | null;
  slug: string | null;
  logo_url: string | null;
  brand_color: string | null;
  tagline: string | null;
  about: string | null;
  is_active: boolean;
}

interface CareerJob {
  id: string;
  title: string | null;
  location: string | null;
  department: string | null;
  employment_type: string | null;
  is_published: boolean | null;
  status: string | null;
}

type SlugStatus = "idle" | "checking" | "available" | "taken";

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function slugify(name: string): string {
  const raw = name
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "")
    .slice(0, 60);
  // DB constraint requires minimum 3 chars starting and ending with alphanumeric.
  // Pad short slugs with a numeric suffix so they always pass the constraint.
  if (raw.length < 3) return raw.padEnd(3, "1");
  return raw;
}

// DB constraint only accepts 6-digit hex (#rrggbb).
// 3-digit shorthand like #fff is NOT accepted by the career_page_brand_color_format check.
function isValidHex(value: string): boolean {
  return /^#[0-9A-Fa-f]{6}$/.test(value);
}

// ---------------------------------------------------------------------------
// Skeleton components
// ---------------------------------------------------------------------------

function ConfigSkeleton() {
  return (
    <div className="space-y-5">
      {[1, 2, 3, 4, 5, 6].map((i) => (
        <div key={i} className="space-y-1.5">
          <Skeleton className="h-4 w-24" />
          <Skeleton className="h-9 w-full" />
        </div>
      ))}
      <Skeleton className="h-9 w-28 mt-2" />
    </div>
  );
}

function JobsSkeleton() {
  return (
    <div className="space-y-0">
      {[1, 2, 3].map((i) => (
        <div key={i} className="flex items-center gap-4 px-4 py-3 border-b border-border last:border-0">
          <Skeleton className="h-4 flex-1" />
          <Skeleton className="h-4 w-24" />
          <Skeleton className="h-4 w-20" />
          <Skeleton className="h-5 w-10 rounded-full" />
        </div>
      ))}
    </div>
  );
}

// ---------------------------------------------------------------------------
// Slug status indicator
// ---------------------------------------------------------------------------

function SlugStatusBadge({ status }: { status: SlugStatus }) {
  if (status === "idle") return null;
  if (status === "checking") {
    return (
      <span className="flex items-center gap-1 text-xs text-muted-foreground">
        <Loader2 className="h-3 w-3 animate-spin" />
        Checking…
      </span>
    );
  }
  if (status === "available") {
    return (
      <Badge variant="outline" className="text-xs border-green-500/50 text-green-600 dark:text-green-400">
        Available
      </Badge>
    );
  }
  return (
    <Badge variant="outline" className="text-xs border-destructive/50 text-destructive">
      Already taken
    </Badge>
  );
}

// ---------------------------------------------------------------------------
// Main page
// ---------------------------------------------------------------------------

const CareerSettings = () => {
  const { user } = useAuth();
  const { team } = useTeam();
  const queryClient = useQueryClient();

  const teamId = team?.id ?? null;
  const userId = user?.id ?? null;

  // ----- Form state -----
  const [companyName, setCompanyName] = useState("");
  const [slug, setSlug] = useState("");
  const [logoUrl, setLogoUrl] = useState("");
  const [brandColor, setBrandColor] = useState("#6366f1");
  const [tagline, setTagline] = useState("");
  const [about, setAbout] = useState("");
  const [isActive, setIsActive] = useState(false);
  const [configId, setConfigId] = useState<string | null>(null);
  const [isSaving, setIsSaving] = useState(false);
  const [slugStatus, setSlugStatus] = useState<SlugStatus>("idle");
  const [slugManuallyEdited, setSlugManuallyEdited] = useState(false);
  const [togglingJobId, setTogglingJobId] = useState<string | null>(null);

  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // ----- Career page URL -----
  const careerPageUrl = slug ? `${window.location.origin}/careers/${slug}` : null;

  // ----- Fetch config -----
  const { data: configData, isLoading: configLoading } = useQuery({
    queryKey: ["career-page-config", teamId],
    queryFn: async () => {
      if (!teamId) return null;
      const { data, error } = await (supabase as any)
        .from("career_page_config")
        .select("*")
        .eq("team_id", teamId)
        .maybeSingle();
      if (error) throw new Error(error.message);
      return data as CareerPageConfig | null;
    },
    enabled: !!teamId,
    staleTime: 60_000,
  });

  // Populate form when config loads
  useEffect(() => {
    if (configData) {
      setConfigId(configData.id);
      setCompanyName(configData.company_name ?? "");
      setSlug(configData.slug ?? "");
      setLogoUrl(configData.logo_url ?? "");
      setBrandColor(configData.brand_color ?? "#6366f1");
      setTagline(configData.tagline ?? "");
      setAbout(configData.about ?? "");
      setIsActive(configData.is_active ?? false);
      setSlugManuallyEdited(true); // Don't auto-overwrite on subsequent renders
    } else if (!configLoading && team?.name) {
      // Pre-fill from team name on first load
      setCompanyName(team.name);
      const auto = slugify(team.name);
      setSlug(auto);
    }
  }, [configData, configLoading, team?.name]);

  // ----- Fetch jobs -----
  const { data: jobs = [], isLoading: jobsLoading } = useQuery({
    queryKey: ["career-jobs", userId],
    queryFn: async () => {
      if (!userId) return [];
      const { data, error } = await (supabase as any)
        .from("jobs")
        .select("id, title, location, department, employment_type, is_published, status")
        .eq("user_id", userId)
        .order("created_at", { ascending: false });
      if (error) throw new Error(error.message);
      return (data ?? []) as CareerJob[];
    },
    enabled: !!userId,
    staleTime: 30_000,
  });

  // ----- Slug auto-gen from company name -----
  const handleCompanyNameChange = (value: string) => {
    setCompanyName(value);
    if (!slugManuallyEdited) {
      const auto = slugify(value);
      setSlug(auto);
      triggerSlugCheck(auto);
    }
  };

  // ----- Slug check debounce -----
  const triggerSlugCheck = useCallback(
    (value: string) => {
      if (debounceRef.current) clearTimeout(debounceRef.current);
      if (!value || !teamId) {
        setSlugStatus("idle");
        return;
      }
      setSlugStatus("checking");
      debounceRef.current = setTimeout(async () => {
        try {
          const { data, error } = await (supabase as any).rpc("is_career_slug_available", {
            p_slug: value,
            p_team_id: teamId,
          });
          if (error) throw error;
          setSlugStatus(data === true ? "available" : "taken");
        } catch {
          setSlugStatus("idle");
        }
      }, 600);
    },
    [teamId]
  );

  const handleSlugChange = (value: string) => {
    const clean = value.toLowerCase().replace(/[^a-z0-9-]/g, "").slice(0, 60);
    setSlug(clean);
    setSlugManuallyEdited(true);
    triggerSlugCheck(clean);
  };

  // Cleanup debounce on unmount
  useEffect(() => {
    return () => {
      if (debounceRef.current) clearTimeout(debounceRef.current);
    };
  }, []);

  // ----- Save config -----
  const handleSave = async () => {
    if (!teamId) {
      toast.error("No team found. Create a team first.");
      return;
    }
    if (!companyName.trim()) {
      toast.error("Company name is required.");
      return;
    }
    if (!slug.trim()) {
      toast.error("URL slug is required.");
      return;
    }
    // DB constraint: ^[a-z0-9][a-z0-9\-]{1,58}[a-z0-9]$ — minimum 3 chars, must start/end with alphanumeric
    if (slug.length < 3) {
      toast.error("Slug must be at least 3 characters.");
      return;
    }
    if (!/^[a-z0-9]/.test(slug) || !/[a-z0-9]$/.test(slug)) {
      toast.error("Slug must start and end with a letter or number.");
      return;
    }
    if (slugStatus === "taken") {
      toast.error("That slug is already taken. Choose a different one.");
      return;
    }

    setIsSaving(true);
    try {
      const payload = {
        team_id: teamId,
        company_name: companyName.trim(),
        slug: slug.trim(),
        logo_url: logoUrl.trim() || null,
        brand_color: isValidHex(brandColor) ? brandColor : "#6366f1",
        tagline: tagline.trim() || null,
        about: about.trim() || null,
        is_active: isActive,
      };

      if (configId) {
        const { error } = await (supabase as any)
          .from("career_page_config")
          .update(payload)
          .eq("id", configId);
        if (error) throw error;
      } else {
        const { data: inserted, error } = await (supabase as any)
          .from("career_page_config")
          .insert(payload)
          .select("id")
          .single();
        if (error) throw error;
        // Capture the new row id so subsequent saves use UPDATE, not INSERT.
        // Without this, a second save attempt would hit the UNIQUE(team_id) constraint.
        if (inserted?.id) {
          setConfigId(inserted.id as string);
        }
      }

      toast.success("Career page saved");
      queryClient.invalidateQueries({ queryKey: ["career-page-config", teamId] });
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : "Failed to save career page";
      toast.error(msg);
    } finally {
      setIsSaving(false);
    }
  };

  // ----- Toggle job published -----
  const toggleJobPublished = useMutation({
    mutationFn: async ({ jobId, current }: { jobId: string; current: boolean }) => {
      const { error } = await (supabase as any)
        .from("jobs")
        .update({ is_published: !current })
        .eq("id", jobId);
      if (error) throw new Error(error.message);
      return { jobId, newValue: !current };
    },
    onMutate: ({ jobId }) => {
      setTogglingJobId(jobId);
    },
    onSuccess: ({ jobId, newValue }) => {
      queryClient.setQueryData(["career-jobs", userId], (old: CareerJob[] | undefined) =>
        (old ?? []).map((j) => (j.id === jobId ? { ...j, is_published: newValue } : j))
      );
      toast.success(newValue ? "Job published to career page" : "Job unpublished");
    },
    onError: (err: unknown) => {
      const msg = err instanceof Error ? err.message : "Failed to update job";
      toast.error(msg);
    },
    onSettled: () => {
      setTogglingJobId(null);
    },
  });

  // ----- Clipboard copy -----
  function copyUrl() {
    if (!careerPageUrl) return;
    navigator.clipboard.writeText(careerPageUrl).then(
      () => toast.success("Link copied"),
      () => toast.error("Could not copy link")
    );
  }

  // ---------------------------------------------------------------------------
  // Render
  // ---------------------------------------------------------------------------

  return (
    <SidebarLayout>
      <main className="w-full max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <FadeIn>
          <div className="flex items-start justify-between mb-1">
            <h1 className="text-2xl font-bold text-foreground">Career Page</h1>
            {isActive && careerPageUrl && (
              <div className="flex items-center gap-1.5">
                <Badge variant="outline" className="text-xs border-green-500/50 text-green-600 dark:text-green-400 gap-1">
                  <Eye className="h-3 w-3" />
                  Live
                </Badge>
                <Button
                  variant="ghost"
                  size="icon"
                  className="h-7 w-7"
                  onClick={copyUrl}
                  aria-label="Copy career page URL"
                >
                  <Copy className="h-3.5 w-3.5" />
                </Button>
                <Button
                  variant="ghost"
                  size="icon"
                  className="h-7 w-7"
                  onClick={() => window.open(careerPageUrl, "_blank")}
                  aria-label="Open career page"
                >
                  <ExternalLink className="h-3.5 w-3.5" />
                </Button>
              </div>
            )}
          </div>
          <p className="text-sm text-muted-foreground mb-6">
            Customize your public career page and manage which jobs are visible to candidates.
          </p>
        </FadeIn>

        <StaggerList className="space-y-6" stagger={0.08}>
          {/* ---------------------------------------------------------------- */}
          {/* Card 1: Configuration                                             */}
          {/* ---------------------------------------------------------------- */}
          <Card className="border border-border/60 shadow-sm">
            <CardHeader className="pb-3">
              <CardTitle className="text-sm font-semibold flex items-center gap-2">
                <Globe className="h-4 w-4 text-primary" />
                Career Page Configuration
              </CardTitle>
              <CardDescription className="text-xs">
                Set up your branded career page. Share the link with candidates.
              </CardDescription>
            </CardHeader>
            <CardContent>
              {configLoading ? (
                <ConfigSkeleton />
              ) : (
                <div className="space-y-5">
                  {/* Company name */}
                  <div className="space-y-1.5">
                    <Label htmlFor="company-name" className="text-xs font-medium">
                      Company name
                    </Label>
                    <Input
                      id="company-name"
                      placeholder="Acme Corp"
                      value={companyName}
                      onChange={(e) => handleCompanyNameChange(e.target.value)}
                      disabled={isSaving}
                    />
                  </div>

                  {/* Slug */}
                  <div className="space-y-1.5">
                    <div className="flex items-center justify-between">
                      <Label htmlFor="slug" className="text-xs font-medium">
                        URL slug
                      </Label>
                      <SlugStatusBadge status={slugStatus} />
                    </div>
                    <div className="flex items-center rounded-md border border-input bg-background ring-offset-background focus-within:ring-2 focus-within:ring-ring focus-within:ring-offset-2 overflow-hidden">
                      <span className="flex items-center pl-3 pr-1 text-xs text-muted-foreground whitespace-nowrap shrink-0 select-none">
                        /careers/
                      </span>
                      <input
                        id="slug"
                        className="flex-1 py-2 pr-3 text-sm bg-transparent outline-none placeholder:text-muted-foreground"
                        placeholder="acme-corp"
                        value={slug}
                        onChange={(e) => handleSlugChange(e.target.value)}
                        disabled={isSaving}
                        spellCheck={false}
                        aria-describedby="slug-hint"
                      />
                    </div>
                    <p id="slug-hint" className="text-xs text-muted-foreground">
                      Lowercase letters, numbers, and hyphens only.
                    </p>
                  </div>

                  {/* Logo URL */}
                  <div className="space-y-1.5">
                    <Label htmlFor="logo-url" className="text-xs font-medium">
                      Logo URL
                    </Label>
                    <Input
                      id="logo-url"
                      placeholder="https://example.com/logo.png"
                      value={logoUrl}
                      onChange={(e) => setLogoUrl(e.target.value)}
                      disabled={isSaving}
                      type="url"
                    />
                  </div>

                  {/* Brand color */}
                  <div className="space-y-1.5">
                    <Label className="text-xs font-medium">Brand color</Label>
                    <div className="flex items-center gap-2">
                      <div className="relative h-9 w-14 shrink-0">
                        <input
                          type="color"
                          className="absolute inset-0 h-full w-full cursor-pointer rounded-md border border-input opacity-0"
                          value={isValidHex(brandColor) ? brandColor : "#6366f1"}
                          onChange={(e) => setBrandColor(e.target.value)}
                          disabled={isSaving}
                          aria-label="Pick brand color"
                        />
                        <div
                          className="h-full w-full rounded-md border border-input"
                          style={{ backgroundColor: isValidHex(brandColor) ? brandColor : "#6366f1" }}
                        />
                      </div>
                      <Input
                        placeholder="#6366f1"
                        value={brandColor}
                        onChange={(e) => setBrandColor(e.target.value)}
                        disabled={isSaving}
                        className="font-mono text-sm w-32"
                        maxLength={7}
                        aria-label="Brand color hex code"
                      />
                      {!isValidHex(brandColor) && brandColor.length > 0 && (
                        <span className="text-xs text-destructive">Use 6-digit hex (e.g. #6366f1)</span>
                      )}
                    </div>
                  </div>

                  {/* Tagline */}
                  <div className="space-y-1.5">
                    <Label htmlFor="tagline" className="text-xs font-medium">
                      Tagline
                    </Label>
                    <Input
                      id="tagline"
                      placeholder="We're building the future of work"
                      value={tagline}
                      onChange={(e) => setTagline(e.target.value)}
                      disabled={isSaving}
                      maxLength={160}
                    />
                  </div>

                  {/* About */}
                  <div className="space-y-1.5">
                    <Label htmlFor="about" className="text-xs font-medium">
                      About
                    </Label>
                    <Textarea
                      id="about"
                      placeholder="Tell candidates about your company, culture, and mission…"
                      value={about}
                      onChange={(e) => setAbout(e.target.value)}
                      disabled={isSaving}
                      rows={4}
                      className="resize-none text-sm"
                      maxLength={2000}
                    />
                  </div>

                  {/* Active toggle */}
                  <div className="flex items-center justify-between rounded-lg border border-border p-3">
                    <div className="space-y-0.5">
                      <Label htmlFor="is-active" className="text-sm font-medium cursor-pointer">
                        Publish career page
                      </Label>
                      <p className="text-xs text-muted-foreground">
                        Make your career page publicly accessible to candidates.
                      </p>
                    </div>
                    <Switch
                      id="is-active"
                      checked={isActive}
                      onCheckedChange={setIsActive}
                      disabled={isSaving}
                      aria-label="Publish career page"
                    />
                  </div>

                  {/* Preview link (when active + slug set) */}
                  {isActive && careerPageUrl && (
                    <div className="flex items-center gap-2 rounded-md bg-muted/50 px-3 py-2">
                      <Globe className="h-3.5 w-3.5 text-muted-foreground shrink-0" />
                      <a
                        href={careerPageUrl}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="flex-1 text-xs text-primary truncate hover:underline"
                      >
                        {careerPageUrl}
                      </a>
                      <button
                        onClick={copyUrl}
                        className="shrink-0 text-muted-foreground hover:text-foreground transition-colors"
                        aria-label="Copy career page URL"
                        type="button"
                      >
                        <Copy className="h-3.5 w-3.5" />
                      </button>
                      <a
                        href={careerPageUrl}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="shrink-0 text-muted-foreground hover:text-foreground transition-colors"
                        aria-label="Open in new tab"
                      >
                        <ExternalLink className="h-3.5 w-3.5" />
                      </a>
                    </div>
                  )}

                  {/* Save button */}
                  <div className="flex justify-end pt-1">
                    <Button
                      onClick={handleSave}
                      disabled={isSaving || slugStatus === "taken"}
                      className="gap-1.5"
                    >
                      {isSaving ? (
                        <Loader2 className="h-4 w-4 animate-spin" />
                      ) : (
                        <Save className="h-4 w-4" />
                      )}
                      Save changes
                    </Button>
                  </div>
                </div>
              )}
            </CardContent>
          </Card>

          {/* ---------------------------------------------------------------- */}
          {/* Card 2: Published Jobs                                            */}
          {/* ---------------------------------------------------------------- */}
          <Card className="border border-border/60 shadow-sm">
            <CardHeader className="pb-3">
              <CardTitle className="text-sm font-semibold flex items-center gap-2">
                <Globe className="h-4 w-4 text-primary" />
                Published Jobs
              </CardTitle>
              <CardDescription className="text-xs">
                Toggle which jobs appear on your career page.
              </CardDescription>
            </CardHeader>
            <CardContent className="p-0">
              {jobsLoading ? (
                <JobsSkeleton />
              ) : jobs.length === 0 ? (
                <div className="flex flex-col items-center justify-center py-14 space-y-3 text-center px-4">
                  <div className="rounded-xl bg-muted/50 p-4">
                    <Globe className="h-7 w-7 text-muted-foreground/40" />
                  </div>
                  <div className="space-y-1">
                    <p className="text-sm font-medium text-foreground">No jobs yet</p>
                    <p className="text-sm text-muted-foreground max-w-xs">
                      Create a job posting from the dashboard to list it on your career page.
                    </p>
                  </div>
                </div>
              ) : (
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead className="text-xs">Title</TableHead>
                      <TableHead className="text-xs hidden sm:table-cell">Location</TableHead>
                      <TableHead className="text-xs hidden md:table-cell">Department</TableHead>
                      <TableHead className="text-xs text-right pr-4">Published</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {jobs.map((job) => {
                      const isToggling = togglingJobId === job.id;
                      const published = job.is_published ?? false;
                      return (
                        <TableRow key={job.id}>
                          <TableCell className="text-sm font-medium max-w-[200px]">
                            <div className="truncate" title={job.title ?? ""}>
                              {job.title || <span className="text-muted-foreground italic">Untitled</span>}
                            </div>
                            {job.employment_type && (
                              <span className="text-xs text-muted-foreground">{job.employment_type}</span>
                            )}
                          </TableCell>
                          <TableCell className="text-sm text-muted-foreground hidden sm:table-cell">
                            {job.location || "—"}
                          </TableCell>
                          <TableCell className="text-sm text-muted-foreground hidden md:table-cell">
                            {job.department || "—"}
                          </TableCell>
                          <TableCell className="text-right pr-4">
                            {isToggling ? (
                              <div className="flex justify-end">
                                <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" />
                              </div>
                            ) : (
                              <Switch
                                checked={published}
                                onCheckedChange={() =>
                                  toggleJobPublished.mutate({ jobId: job.id, current: published })
                                }
                                disabled={isToggling}
                                aria-label={`${published ? "Unpublish" : "Publish"} ${job.title ?? "job"}`}
                              />
                            )}
                          </TableCell>
                        </TableRow>
                      );
                    })}
                  </TableBody>
                </Table>
              )}
            </CardContent>
          </Card>
        </StaggerList>
      </main>
    </SidebarLayout>
  );
};

export default CareerSettings;

import { useState, useEffect, useRef, useCallback } from "react";
import { toast } from "sonner";
import { Globe, Copy, ExternalLink, Loader2, Save, Eye } from "lucide-react";
import SidebarLayout from "@/components/SidebarLayout";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import { useTeam } from "@/hooks/useTeam";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface CareerPageConfig {
  id: string;
  team_id: string;
  company_name: string | null;
  slug: string | null;
  logo_url: string | null;
  brand_color: string | null;
  tagline: string | null;
  about: string | null;
  is_active: boolean;
}

interface CareerJob {
  id: string;
  title: string | null;
  location: string | null;
  department: string | null;
  employment_type: string | null;
  is_published: boolean | null;
  status: string | null;
}

type SlugStatus = "idle" | "checking" | "available" | "taken";

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function slugify(name: string): string {
  const raw = name
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "")
    .slice(0, 60);
  // DB constraint requires minimum 3 chars starting and ending with alphanumeric.
  // Pad short slugs with a numeric suffix so they always pass the constraint.
  if (raw.length < 3) return raw.padEnd(3, "1");
  return raw;
}

// DB constraint only accepts 6-digit hex (#rrggbb).
// 3-digit shorthand like #fff is NOT accepted by the career_page_brand_color_format check.
function isValidHex(value: string): boolean {
  return /^#[0-9A-Fa-f]{6}$/.test(value);
}

// ---------------------------------------------------------------------------
// Skeleton components
// ---------------------------------------------------------------------------

function ConfigSkeleton() {
  return (
    <div className="space-y-5">
      {[1, 2, 3, 4, 5, 6].map((i) => (
        <div key={i} className="space-y-1.5">
          <Skeleton className="h-4 w-24" />
          <Skeleton className="h-9 w-full" />
        </div>
      ))}
      <Skeleton className="h-9 w-28 mt-2" />
    </div>
  );
}

function JobsSkeleton() {
  return (
    <div className="space-y-0">
      {[1, 2, 3].map((i) => (
        <div key={i} className="flex items-center gap-4 px-4 py-3 border-b border-border last:border-0">
          <Skeleton className="h-4 flex-1" />
          <Skeleton className="h-4 w-24" />
          <Skeleton className="h-4 w-20" />
          <Skeleton className="h-5 w-10 rounded-full" />
        </div>
      ))}
    </div>
  );
}

// ---------------------------------------------------------------------------
// Slug status indicator
// ---------------------------------------------------------------------------

function SlugStatusBadge({ status }: { status: SlugStatus }) {
  if (status === "idle") return null;
  if (status === "checking") {
    return (
      <span className="flex items-center gap-1 text-xs text-muted-foreground">
        <Loader2 className="h-3 w-3 animate-spin" />
        Checking…
      </span>
    );
  }
  if (status === "available") {
    return (
      <Badge variant="outline" className="text-xs border-green-500/50 text-green-600 dark:text-green-400">
        Available
      </Badge>
    );
  }
  return (
    <Badge variant="outline" className="text-xs border-destructive/50 text-destructive">
      Already taken
    </Badge>
  );
}

// ---------------------------------------------------------------------------
// Main page
// ---------------------------------------------------------------------------

const CareerSettings = () => {
  const { user } = useAuth();
  const { team } = useTeam();
  const queryClient = useQueryClient();

  const teamId = team?.id ?? null;
  const userId = user?.id ?? null;

  // ----- Form state -----
  const [companyName, setCompanyName] = useState("");
  const [slug, setSlug] = useState("");
  const [logoUrl, setLogoUrl] = useState("");
  const [brandColor, setBrandColor] = useState("#6366f1");
  const [tagline, setTagline] = useState("");
  const [about, setAbout] = useState("");
  const [isActive, setIsActive] = useState(false);
  const [configId, setConfigId] = useState<string | null>(null);
  const [isSaving, setIsSaving] = useState(false);
  const [slugStatus, setSlugStatus] = useState<SlugStatus>("idle");
  const [slugManuallyEdited, setSlugManuallyEdited] = useState(false);
  const [togglingJobId, setTogglingJobId] = useState<string | null>(null);

  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // ----- Career page URL -----
  const careerPageUrl = slug ? `${window.location.origin}/careers/${slug}` : null;

  // ----- Fetch config -----
  const { data: configData, isLoading: configLoading } = useQuery({
    queryKey: ["career-page-config", teamId],
    queryFn: async () => {
      if (!teamId) return null;
      const { data, error } = await (supabase as any)
        .from("career_page_config")
        .select("*")
        .eq("team_id", teamId)
        .maybeSingle();
      if (error) throw new Error(error.message);
      return data as CareerPageConfig | null;
    },
    enabled: !!teamId,
    staleTime: 60_000,
  });

  // Populate form when config loads
  useEffect(() => {
    if (configData) {
      setConfigId(configData.id);
      setCompanyName(configData.company_name ?? "");
      setSlug(configData.slug ?? "");
      setLogoUrl(configData.logo_url ?? "");
      setBrandColor(configData.brand_color ?? "#6366f1");
      setTagline(configData.tagline ?? "");
      setAbout(configData.about ?? "");
      setIsActive(configData.is_active ?? false);
      setSlugManuallyEdited(true); // Don't auto-overwrite on subsequent renders
    } else if (!configLoading && team?.name) {
      // Pre-fill from team name on first load
      setCompanyName(team.name);
      const auto = slugify(team.name);
      setSlug(auto);
    }
  }, [configData, configLoading, team?.name]);

  // ----- Fetch jobs -----
  const { data: jobs = [], isLoading: jobsLoading } = useQuery({
    queryKey: ["career-jobs", userId],
    queryFn: async () => {
      if (!userId) return [];
      const { data, error } = await (supabase as any)
        .from("jobs")
        .select("id, title, location, department, employment_type, is_published, status")
        .eq("user_id", userId)
        .order("created_at", { ascending: false });
      if (error) throw new Error(error.message);
      return (data ?? []) as CareerJob[];
    },
    enabled: !!userId,
    staleTime: 30_000,
  });

  // ----- Slug auto-gen from company name -----
  const handleCompanyNameChange = (value: string) => {
    setCompanyName(value);
    if (!slugManuallyEdited) {
      const auto = slugify(value);
      setSlug(auto);
      triggerSlugCheck(auto);
    }
  };

  // ----- Slug check debounce -----
  const triggerSlugCheck = useCallback(
    (value: string) => {
      if (debounceRef.current) clearTimeout(debounceRef.current);
      if (!value || !teamId) {
        setSlugStatus("idle");
        return;
      }
      setSlugStatus("checking");
      debounceRef.current = setTimeout(async () => {
        try {
          const { data, error } = await (supabase as any).rpc("is_career_slug_available", {
            p_slug: value,
            p_team_id: teamId,
          });
          if (error) throw error;
          setSlugStatus(data === true ? "available" : "taken");
        } catch {
          setSlugStatus("idle");
        }
      }, 600);
    },
    [teamId]
  );

  const handleSlugChange = (value: string) => {
    const clean = value.toLowerCase().replace(/[^a-z0-9-]/g, "").slice(0, 60);
    setSlug(clean);
    setSlugManuallyEdited(true);
    triggerSlugCheck(clean);
  };

  // Cleanup debounce on unmount
  useEffect(() => {
    return () => {
      if (debounceRef.current) clearTimeout(debounceRef.current);
    };
  }, []);

  // ----- Save config -----
  const handleSave = async () => {
    if (!teamId) {
      toast.error("No team found. Create a team first.");
      return;
    }
    if (!companyName.trim()) {
      toast.error("Company name is required.");
      return;
    }
    if (!slug.trim()) {
      toast.error("URL slug is required.");
      return;
    }
    // DB constraint: ^[a-z0-9][a-z0-9\-]{1,58}[a-z0-9]$ — minimum 3 chars, must start/end with alphanumeric
    if (slug.length < 3) {
      toast.error("Slug must be at least 3 characters.");
      return;
    }
    if (!/^[a-z0-9]/.test(slug) || !/[a-z0-9]$/.test(slug)) {
      toast.error("Slug must start and end with a letter or number.");
      return;
    }
    if (slugStatus === "taken") {
      toast.error("That slug is already taken. Choose a different one.");
      return;
    }

    setIsSaving(true);
    try {
      const payload = {
        team_id: teamId,
        company_name: companyName.trim(),
        slug: slug.trim(),
        logo_url: logoUrl.trim() || null,
        brand_color: isValidHex(brandColor) ? brandColor : "#6366f1",
        tagline: tagline.trim() || null,
        about: about.trim() || null,
        is_active: isActive,
      };

      if (configId) {
        const { error } = await (supabase as any)
          .from("career_page_config")
          .update(payload)
          .eq("id", configId);
        if (error) throw error;
      } else {
        const { data: inserted, error } = await (supabase as any)
          .from("career_page_config")
          .insert(payload)
          .select("id")
          .single();
        if (error) throw error;
        // Capture the new row id so subsequent saves use UPDATE, not INSERT.
        // Without this, a second save attempt would hit the UNIQUE(team_id) constraint.
        if (inserted?.id) {
          setConfigId(inserted.id as string);
        }
      }

      toast.success("Career page saved");
      queryClient.invalidateQueries({ queryKey: ["career-page-config", teamId] });
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : "Failed to save career page";
      toast.error(msg);
    } finally {
      setIsSaving(false);
    }
  };

  // ----- Toggle job published -----
  const toggleJobPublished = useMutation({
    mutationFn: async ({ jobId, current }: { jobId: string; current: boolean }) => {
      const { error } = await (supabase as any)
        .from("jobs")
        .update({ is_published: !current })
        .eq("id", jobId);
      if (error) throw new Error(error.message);
      return { jobId, newValue: !current };
    },
    onMutate: ({ jobId }) => {
      setTogglingJobId(jobId);
    },
    onSuccess: ({ jobId, newValue }) => {
      queryClient.setQueryData(["career-jobs", userId], (old: CareerJob[] | undefined) =>
        (old ?? []).map((j) => (j.id === jobId ? { ...j, is_published: newValue } : j))
      );
      toast.success(newValue ? "Job published to career page" : "Job unpublished");
    },
    onError: (err: unknown) => {
      const msg = err instanceof Error ? err.message : "Failed to update job";
      toast.error(msg);
    },
    onSettled: () => {
      setTogglingJobId(null);
    },
  });

  // ----- Clipboard copy -----
  function copyUrl() {
    if (!careerPageUrl) return;
    navigator.clipboard.writeText(careerPageUrl).then(
      () => toast.success("Link copied"),
      () => toast.error("Could not copy link")
    );
  }

  // ---------------------------------------------------------------------------
  // Render
  // ---------------------------------------------------------------------------

  return (
    <SidebarLayout>
      <main className="w-full max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <FadeIn>
          <div className="flex items-start justify-between mb-1">
            <h1 className="text-2xl font-bold text-foreground">Career Page</h1>
            {isActive && careerPageUrl && (
              <div className="flex items-center gap-1.5">
                <Badge variant="outline" className="text-xs border-green-500/50 text-green-600 dark:text-green-400 gap-1">
                  <Eye className="h-3 w-3" />
                  Live
                </Badge>
                <Button
                  variant="ghost"
                  size="icon"
                  className="h-7 w-7"
                  onClick={copyUrl}
                  aria-label="Copy career page URL"
                >
                  <Copy className="h-3.5 w-3.5" />
                </Button>
                <Button
                  variant="ghost"
                  size="icon"
                  className="h-7 w-7"
                  onClick={() => window.open(careerPageUrl, "_blank")}
                  aria-label="Open career page"
                >
                  <ExternalLink className="h-3.5 w-3.5" />
                </Button>
              </div>
            )}
          </div>
          <p className="text-sm text-muted-foreground mb-6">
            Customize your public career page and manage which jobs are visible to candidates.
          </p>
        </FadeIn>

        <StaggerList className="space-y-6" stagger={0.08}>
          {/* ---------------------------------------------------------------- */}
          {/* Card 1: Configuration                                             */}
          {/* ---------------------------------------------------------------- */}
          <Card className="border border-border/60 shadow-sm">
            <CardHeader className="pb-3">
              <CardTitle className="text-sm font-semibold flex items-center gap-2">
                <Globe className="h-4 w-4 text-primary" />
                Career Page Configuration
              </CardTitle>
              <CardDescription className="text-xs">
                Set up your branded career page. Share the link with candidates.
              </CardDescription>
            </CardHeader>
            <CardContent>
              {configLoading ? (
                <ConfigSkeleton />
              ) : (
                <div className="space-y-5">
                  {/* Company name */}
                  <div className="space-y-1.5">
                    <Label htmlFor="company-name" className="text-xs font-medium">
                      Company name
                    </Label>
                    <Input
                      id="company-name"
                      placeholder="Acme Corp"
                      value={companyName}
                      onChange={(e) => handleCompanyNameChange(e.target.value)}
                      disabled={isSaving}
                    />
                  </div>

                  {/* Slug */}
                  <div className="space-y-1.5">
                    <div className="flex items-center justify-between">
                      <Label htmlFor="slug" className="text-xs font-medium">
                        URL slug
                      </Label>
                      <SlugStatusBadge status={slugStatus} />
                    </div>
                    <div className="flex items-center rounded-md border border-input bg-background ring-offset-background focus-within:ring-2 focus-within:ring-ring focus-within:ring-offset-2 overflow-hidden">
                      <span className="flex items-center pl-3 pr-1 text-xs text-muted-foreground whitespace-nowrap shrink-0 select-none">
                        /careers/
                      </span>
                      <input
                        id="slug"
                        className="flex-1 py-2 pr-3 text-sm bg-transparent outline-none placeholder:text-muted-foreground"
                        placeholder="acme-corp"
                        value={slug}
                        onChange={(e) => handleSlugChange(e.target.value)}
                        disabled={isSaving}
                        spellCheck={false}
                        aria-describedby="slug-hint"
                      />
                    </div>
                    <p id="slug-hint" className="text-xs text-muted-foreground">
                      Lowercase letters, numbers, and hyphens only.
                    </p>
                  </div>

                  {/* Logo URL */}
                  <div className="space-y-1.5">
                    <Label htmlFor="logo-url" className="text-xs font-medium">
                      Logo URL
                    </Label>
                    <Input
                      id="logo-url"
                      placeholder="https://example.com/logo.png"
                      value={logoUrl}
                      onChange={(e) => setLogoUrl(e.target.value)}
                      disabled={isSaving}
                      type="url"
                    />
                  </div>

                  {/* Brand color */}
                  <div className="space-y-1.5">
                    <Label className="text-xs font-medium">Brand color</Label>
                    <div className="flex items-center gap-2">
                      <div className="relative h-9 w-14 shrink-0">
                        <input
                          type="color"
                          className="absolute inset-0 h-full w-full cursor-pointer rounded-md border border-input opacity-0"
                          value={isValidHex(brandColor) ? brandColor : "#6366f1"}
                          onChange={(e) => setBrandColor(e.target.value)}
                          disabled={isSaving}
                          aria-label="Pick brand color"
                        />
                        <div
                          className="h-full w-full rounded-md border border-input"
                          style={{ backgroundColor: isValidHex(brandColor) ? brandColor : "#6366f1" }}
                        />
                      </div>
                      <Input
                        placeholder="#6366f1"
                        value={brandColor}
                        onChange={(e) => setBrandColor(e.target.value)}
                        disabled={isSaving}
                        className="font-mono text-sm w-32"
                        maxLength={7}
                        aria-label="Brand color hex code"
                      />
                      {!isValidHex(brandColor) && brandColor.length > 0 && (
                        <span className="text-xs text-destructive">Use 6-digit hex (e.g. #6366f1)</span>
                      )}
                    </div>
                  </div>

                  {/* Tagline */}
                  <div className="space-y-1.5">
                    <Label htmlFor="tagline" className="text-xs font-medium">
                      Tagline
                    </Label>
                    <Input
                      id="tagline"
                      placeholder="We're building the future of work"
                      value={tagline}
                      onChange={(e) => setTagline(e.target.value)}
                      disabled={isSaving}
                      maxLength={160}
                    />
                  </div>

                  {/* About */}
                  <div className="space-y-1.5">
                    <Label htmlFor="about" className="text-xs font-medium">
                      About
                    </Label>
                    <Textarea
                      id="about"
                      placeholder="Tell candidates about your company, culture, and mission…"
                      value={about}
                      onChange={(e) => setAbout(e.target.value)}
                      disabled={isSaving}
                      rows={4}
                      className="resize-none text-sm"
                      maxLength={2000}
                    />
                  </div>

                  {/* Active toggle */}
                  <div className="flex items-center justify-between rounded-lg border border-border p-3">
                    <div className="space-y-0.5">
                      <Label htmlFor="is-active" className="text-sm font-medium cursor-pointer">
                        Publish career page
                      </Label>
                      <p className="text-xs text-muted-foreground">
                        Make your career page publicly accessible to candidates.
                      </p>
                    </div>
                    <Switch
                      id="is-active"
                      checked={isActive}
                      onCheckedChange={setIsActive}
                      disabled={isSaving}
                      aria-label="Publish career page"
                    />
                  </div>

                  {/* Preview link (when active + slug set) */}
                  {isActive && careerPageUrl && (
                    <div className="flex items-center gap-2 rounded-md bg-muted/50 px-3 py-2">
                      <Globe className="h-3.5 w-3.5 text-muted-foreground shrink-0" />
                      <a
                        href={careerPageUrl}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="flex-1 text-xs text-primary truncate hover:underline"
                      >
                        {careerPageUrl}
                      </a>
                      <button
                        onClick={copyUrl}
                        className="shrink-0 text-muted-foreground hover:text-foreground transition-colors"
                        aria-label="Copy career page URL"
                        type="button"
                      >
                        <Copy className="h-3.5 w-3.5" />
                      </button>
                      <a
                        href={careerPageUrl}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="shrink-0 text-muted-foreground hover:text-foreground transition-colors"
                        aria-label="Open in new tab"
                      >
                        <ExternalLink className="h-3.5 w-3.5" />
                      </a>
                    </div>
                  )}

                  {/* Save button */}
                  <div className="flex justify-end pt-1">
                    <Button
                      onClick={handleSave}
                      disabled={isSaving || slugStatus === "taken"}
                      className="gap-1.5"
                    >
                      {isSaving ? (
                        <Loader2 className="h-4 w-4 animate-spin" />
                      ) : (
                        <Save className="h-4 w-4" />
                      )}
                      Save changes
                    </Button>
                  </div>
                </div>
              )}
            </CardContent>
          </Card>

          {/* ---------------------------------------------------------------- */}
          {/* Card 2: Published Jobs                                            */}
          {/* ---------------------------------------------------------------- */}
          <Card className="border border-border/60 shadow-sm">
            <CardHeader className="pb-3">
              <CardTitle className="text-sm font-semibold flex items-center gap-2">
                <Globe className="h-4 w-4 text-primary" />
                Published Jobs
              </CardTitle>
              <CardDescription className="text-xs">
                Toggle which jobs appear on your career page.
              </CardDescription>
            </CardHeader>
            <CardContent className="p-0">
              {jobsLoading ? (
                <JobsSkeleton />
              ) : jobs.length === 0 ? (
                <div className="flex flex-col items-center justify-center py-14 space-y-3 text-center px-4">
                  <div className="rounded-xl bg-muted/50 p-4">
                    <Globe className="h-7 w-7 text-muted-foreground/40" />
                  </div>
                  <div className="space-y-1">
                    <p className="text-sm font-medium text-foreground">No jobs yet</p>
                    <p className="text-sm text-muted-foreground max-w-xs">
                      Create a job posting from the dashboard to list it on your career page.
                    </p>
                  </div>
                </div>
              ) : (
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead className="text-xs">Title</TableHead>
                      <TableHead className="text-xs hidden sm:table-cell">Location</TableHead>
                      <TableHead className="text-xs hidden md:table-cell">Department</TableHead>
                      <TableHead className="text-xs text-right pr-4">Published</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {jobs.map((job) => {
                      const isToggling = togglingJobId === job.id;
                      const published = job.is_published ?? false;
                      return (
                        <TableRow key={job.id}>
                          <TableCell className="text-sm font-medium max-w-[200px]">
                            <div className="truncate" title={job.title ?? ""}>
                              {job.title || <span className="text-muted-foreground italic">Untitled</span>}
                            </div>
                            {job.employment_type && (
                              <span className="text-xs text-muted-foreground">{job.employment_type}</span>
                            )}
                          </TableCell>
                          <TableCell className="text-sm text-muted-foreground hidden sm:table-cell">
                            {job.location || "—"}
                          </TableCell>
                          <TableCell className="text-sm text-muted-foreground hidden md:table-cell">
                            {job.department || "—"}
                          </TableCell>
                          <TableCell className="text-right pr-4">
                            {isToggling ? (
                              <div className="flex justify-end">
                                <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" />
                              </div>
                            ) : (
                              <Switch
                                checked={published}
                                onCheckedChange={() =>
                                  toggleJobPublished.mutate({ jobId: job.id, current: published })
                                }
                                disabled={isToggling}
                                aria-label={`${published ? "Unpublish" : "Publish"} ${job.title ?? "job"}`}
                              />
                            )}
                          </TableCell>
                        </TableRow>
                      );
                    })}
                  </TableBody>
                </Table>
              )}
            </CardContent>
          </Card>
        </StaggerList>
      </main>
    </SidebarLayout>
  );
};

export default CareerSettings;

import { useState, useEffect, useRef, useCallback } from "react";
import { toast } from "sonner";
import { Globe, Copy, ExternalLink, Loader2, Save, Eye } from "lucide-react";
import SidebarLayout from "@/components/SidebarLayout";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import { useTeam } from "@/hooks/useTeam";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface CareerPageConfig {
  id: string;
  team_id: string;
  company_name: string | null;
  slug: string | null;
  logo_url: string | null;
  brand_color: string | null;
  tagline: string | null;
  about: string | null;
  is_active: boolean;
}

interface CareerJob {
  id: string;
  title: string | null;
  location: string | null;
  department: string | null;
  employment_type: string | null;
  is_published: boolean | null;
  status: string | null;
}

type SlugStatus = "idle" | "checking" | "available" | "taken";

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function slugify(name: string): string {
  const raw = name
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "")
    .slice(0, 60);
  // DB constraint requires minimum 3 chars starting and ending with alphanumeric.
  // Pad short slugs with a numeric suffix so they always pass the constraint.
  if (raw.length < 3) return raw.padEnd(3, "1");
  return raw;
}

// DB constraint only accepts 6-digit hex (#rrggbb).
// 3-digit shorthand like #fff is NOT accepted by the career_page_brand_color_format check.
function isValidHex(value: string): boolean {
  return /^#[0-9A-Fa-f]{6}$/.test(value);
}

// ---------------------------------------------------------------------------
// Skeleton components
// ---------------------------------------------------------------------------

function ConfigSkeleton() {
  return (
    <div className="space-y-5">
      {[1, 2, 3, 4, 5, 6].map((i) => (
        <div key={i} className="space-y-1.5">
          <Skeleton className="h-4 w-24" />
          <Skeleton className="h-9 w-full" />
        </div>
      ))}
      <Skeleton className="h-9 w-28 mt-2" />
    </div>
  );
}

function JobsSkeleton() {
  return (
    <div className="space-y-0">
      {[1, 2, 3].map((i) => (
        <div key={i} className="flex items-center gap-4 px-4 py-3 border-b border-border last:border-0">
          <Skeleton className="h-4 flex-1" />
          <Skeleton className="h-4 w-24" />
          <Skeleton className="h-4 w-20" />
          <Skeleton className="h-5 w-10 rounded-full" />
        </div>
      ))}
    </div>
  );
}

// ---------------------------------------------------------------------------
// Slug status indicator
// ---------------------------------------------------------------------------

function SlugStatusBadge({ status }: { status: SlugStatus }) {
  if (status === "idle") return null;
  if (status === "checking") {
    return (
      <span className="flex items-center gap-1 text-xs text-muted-foreground">
        <Loader2 className="h-3 w-3 animate-spin" />
        Checking…
      </span>
    );
  }
  if (status === "available") {
    return (
      <Badge variant="outline" className="text-xs border-green-500/50 text-green-600 dark:text-green-400">
        Available
      </Badge>
    );
  }
  return (
    <Badge variant="outline" className="text-xs border-destructive/50 text-destructive">
      Already taken
    </Badge>
  );
}

// ---------------------------------------------------------------------------
// Main page
// ---------------------------------------------------------------------------

const CareerSettings = () => {
  const { user } = useAuth();
  const { team } = useTeam();
  const queryClient = useQueryClient();

  const teamId = team?.id ?? null;
  const userId = user?.id ?? null;

  // ----- Form state -----
  const [companyName, setCompanyName] = useState("");
  const [slug, setSlug] = useState("");
  const [logoUrl, setLogoUrl] = useState("");
  const [brandColor, setBrandColor] = useState("#6366f1");
  const [tagline, setTagline] = useState("");
  const [about, setAbout] = useState("");
  const [isActive, setIsActive] = useState(false);
  const [configId, setConfigId] = useState<string | null>(null);
  const [isSaving, setIsSaving] = useState(false);
  const [slugStatus, setSlugStatus] = useState<SlugStatus>("idle");
  const [slugManuallyEdited, setSlugManuallyEdited] = useState(false);
  const [togglingJobId, setTogglingJobId] = useState<string | null>(null);

  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // ----- Career page URL -----
  const careerPageUrl = slug ? `${window.location.origin}/careers/${slug}` : null;

  // ----- Fetch config -----
  const { data: configData, isLoading: configLoading } = useQuery({
    queryKey: ["career-page-config", teamId],
    queryFn: async () => {
      if (!teamId) return null;
      const { data, error } = await (supabase as any)
        .from("career_page_config")
        .select("*")
        .eq("team_id", teamId)
        .maybeSingle();
      if (error) throw new Error(error.message);
      return data as CareerPageConfig | null;
    },
    enabled: !!teamId,
    staleTime: 60_000,
  });

  // Populate form when config loads
  useEffect(() => {
    if (configData) {
      setConfigId(configData.id);
      setCompanyName(configData.company_name ?? "");
      setSlug(configData.slug ?? "");
      setLogoUrl(configData.logo_url ?? "");
      setBrandColor(configData.brand_color ?? "#6366f1");
      setTagline(configData.tagline ?? "");
      setAbout(configData.about ?? "");
      setIsActive(configData.is_active ?? false);
      setSlugManuallyEdited(true); // Don't auto-overwrite on subsequent renders
    } else if (!configLoading && team?.name) {
      // Pre-fill from team name on first load
      setCompanyName(team.name);
      const auto = slugify(team.name);
      setSlug(auto);
    }
  }, [configData, configLoading, team?.name]);

  // ----- Fetch jobs -----
  const { data: jobs = [], isLoading: jobsLoading } = useQuery({
    queryKey: ["career-jobs", userId],
    queryFn: async () => {
      if (!userId) return [];
      const { data, error } = await (supabase as any)
        .from("jobs")
        .select("id, title, location, department, employment_type, is_published, status")
        .eq("user_id", userId)
        .order("created_at", { ascending: false });
      if (error) throw new Error(error.message);
      return (data ?? []) as CareerJob[];
    },
    enabled: !!userId,
    staleTime: 30_000,
  });

  // ----- Slug auto-gen from company name -----
  const handleCompanyNameChange = (value: string) => {
    setCompanyName(value);
    if (!slugManuallyEdited) {
      const auto = slugify(value);
      setSlug(auto);
      triggerSlugCheck(auto);
    }
  };

  // ----- Slug check debounce -----
  const triggerSlugCheck = useCallback(
    (value: string) => {
      if (debounceRef.current) clearTimeout(debounceRef.current);
      if (!value || !teamId) {
        setSlugStatus("idle");
        return;
      }
      setSlugStatus("checking");
      debounceRef.current = setTimeout(async () => {
        try {
          const { data, error } = await (supabase as any).rpc("is_career_slug_available", {
            p_slug: value,
            p_team_id: teamId,
          });
          if (error) throw error;
          setSlugStatus(data === true ? "available" : "taken");
        } catch {
          setSlugStatus("idle");
        }
      }, 600);
    },
    [teamId]
  );

  const handleSlugChange = (value: string) => {
    const clean = value.toLowerCase().replace(/[^a-z0-9-]/g, "").slice(0, 60);
    setSlug(clean);
    setSlugManuallyEdited(true);
    triggerSlugCheck(clean);
  };

  // Cleanup debounce on unmount
  useEffect(() => {
    return () => {
      if (debounceRef.current) clearTimeout(debounceRef.current);
    };
  }, []);

  // ----- Save config -----
  const handleSave = async () => {
    if (!teamId) {
      toast.error("No team found. Create a team first.");
      return;
    }
    if (!companyName.trim()) {
      toast.error("Company name is required.");
      return;
    }
    if (!slug.trim()) {
      toast.error("URL slug is required.");
      return;
    }
    // DB constraint: ^[a-z0-9][a-z0-9\-]{1,58}[a-z0-9]$ — minimum 3 chars, must start/end with alphanumeric
    if (slug.length < 3) {
      toast.error("Slug must be at least 3 characters.");
      return;
    }
    if (!/^[a-z0-9]/.test(slug) || !/[a-z0-9]$/.test(slug)) {
      toast.error("Slug must start and end with a letter or number.");
      return;
    }
    if (slugStatus === "taken") {
      toast.error("That slug is already taken. Choose a different one.");
      return;
    }

    setIsSaving(true);
    try {
      const payload = {
        team_id: teamId,
        company_name: companyName.trim(),
        slug: slug.trim(),
        logo_url: logoUrl.trim() || null,
        brand_color: isValidHex(brandColor) ? brandColor : "#6366f1",
        tagline: tagline.trim() || null,
        about: about.trim() || null,
        is_active: isActive,
      };

      if (configId) {
        const { error } = await (supabase as any)
          .from("career_page_config")
          .update(payload)
          .eq("id", configId);
        if (error) throw error;
      } else {
        const { data: inserted, error } = await (supabase as any)
          .from("career_page_config")
          .insert(payload)
          .select("id")
          .single();
        if (error) throw error;
        // Capture the new row id so subsequent saves use UPDATE, not INSERT.
        // Without this, a second save attempt would hit the UNIQUE(team_id) constraint.
        if (inserted?.id) {
          setConfigId(inserted.id as string);
        }
      }

      toast.success("Career page saved");
      queryClient.invalidateQueries({ queryKey: ["career-page-config", teamId] });
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : "Failed to save career page";
      toast.error(msg);
    } finally {
      setIsSaving(false);
    }
  };

  // ----- Toggle job published -----
  const toggleJobPublished = useMutation({
    mutationFn: async ({ jobId, current }: { jobId: string; current: boolean }) => {
      const { error } = await (supabase as any)
        .from("jobs")
        .update({ is_published: !current })
        .eq("id", jobId);
      if (error) throw new Error(error.message);
      return { jobId, newValue: !current };
    },
    onMutate: ({ jobId }) => {
      setTogglingJobId(jobId);
    },
    onSuccess: ({ jobId, newValue }) => {
      queryClient.setQueryData(["career-jobs", userId], (old: CareerJob[] | undefined) =>
        (old ?? []).map((j) => (j.id === jobId ? { ...j, is_published: newValue } : j))
      );
      toast.success(newValue ? "Job published to career page" : "Job unpublished");
    },
    onError: (err: unknown) => {
      const msg = err instanceof Error ? err.message : "Failed to update job";
      toast.error(msg);
    },
    onSettled: () => {
      setTogglingJobId(null);
    },
  });

  // ----- Clipboard copy -----
  function copyUrl() {
    if (!careerPageUrl) return;
    navigator.clipboard.writeText(careerPageUrl).then(
      () => toast.success("Link copied"),
      () => toast.error("Could not copy link")
    );
  }

  // ---------------------------------------------------------------------------
  // Render
  // ---------------------------------------------------------------------------

  return (
    <SidebarLayout>
      <main className="w-full max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="flex items-start justify-between mb-1">
          <h1 className="text-2xl font-bold text-foreground">Career Page</h1>
          {isActive && careerPageUrl && (
            <div className="flex items-center gap-1.5">
              <Badge variant="outline" className="text-xs border-green-500/50 text-green-600 dark:text-green-400 gap-1">
                <Eye className="h-3 w-3" />
                Live
              </Badge>
              <Button
                variant="ghost"
                size="icon"
                className="h-7 w-7"
                onClick={copyUrl}
                aria-label="Copy career page URL"
              >
                <Copy className="h-3.5 w-3.5" />
              </Button>
              <Button
                variant="ghost"
                size="icon"
                className="h-7 w-7"
                onClick={() => window.open(careerPageUrl, "_blank")}
                aria-label="Open career page"
              >
                <ExternalLink className="h-3.5 w-3.5" />
              </Button>
            </div>
          )}
        </div>
        <p className="text-sm text-muted-foreground mb-6">
          Customize your public career page and manage which jobs are visible to candidates.
        </p>

        <div className="space-y-6">
          {/* ---------------------------------------------------------------- */}
          {/* Card 1: Configuration                                             */}
          {/* ---------------------------------------------------------------- */}
          <Card className="border border-border/60 shadow-sm">
            <CardHeader className="pb-3">
              <CardTitle className="text-sm font-semibold flex items-center gap-2">
                <Globe className="h-4 w-4 text-primary" />
                Career Page Configuration
              </CardTitle>
              <CardDescription className="text-xs">
                Set up your branded career page. Share the link with candidates.
              </CardDescription>
            </CardHeader>
            <CardContent>
              {configLoading ? (
                <ConfigSkeleton />
              ) : (
                <div className="space-y-5">
                  {/* Company name */}
                  <div className="space-y-1.5">
                    <Label htmlFor="company-name" className="text-xs font-medium">
                      Company name
                    </Label>
                    <Input
                      id="company-name"
                      placeholder="Acme Corp"
                      value={companyName}
                      onChange={(e) => handleCompanyNameChange(e.target.value)}
                      disabled={isSaving}
                    />
                  </div>

                  {/* Slug */}
                  <div className="space-y-1.5">
                    <div className="flex items-center justify-between">
                      <Label htmlFor="slug" className="text-xs font-medium">
                        URL slug
                      </Label>
                      <SlugStatusBadge status={slugStatus} />
                    </div>
                    <div className="flex items-center rounded-md border border-input bg-background ring-offset-background focus-within:ring-2 focus-within:ring-ring focus-within:ring-offset-2 overflow-hidden">
                      <span className="flex items-center pl-3 pr-1 text-xs text-muted-foreground whitespace-nowrap shrink-0 select-none">
                        /careers/
                      </span>
                      <input
                        id="slug"
                        className="flex-1 py-2 pr-3 text-sm bg-transparent outline-none placeholder:text-muted-foreground"
                        placeholder="acme-corp"
                        value={slug}
                        onChange={(e) => handleSlugChange(e.target.value)}
                        disabled={isSaving}
                        spellCheck={false}
                        aria-describedby="slug-hint"
                      />
                    </div>
                    <p id="slug-hint" className="text-xs text-muted-foreground">
                      Lowercase letters, numbers, and hyphens only.
                    </p>
                  </div>

                  {/* Logo URL */}
                  <div className="space-y-1.5">
                    <Label htmlFor="logo-url" className="text-xs font-medium">
                      Logo URL
                    </Label>
                    <Input
                      id="logo-url"
                      placeholder="https://example.com/logo.png"
                      value={logoUrl}
                      onChange={(e) => setLogoUrl(e.target.value)}
                      disabled={isSaving}
                      type="url"
                    />
                  </div>

                  {/* Brand color */}
                  <div className="space-y-1.5">
                    <Label className="text-xs font-medium">Brand color</Label>
                    <div className="flex items-center gap-2">
                      <div className="relative h-9 w-14 shrink-0">
                        <input
                          type="color"
                          className="absolute inset-0 h-full w-full cursor-pointer rounded-md border border-input opacity-0"
                          value={isValidHex(brandColor) ? brandColor : "#6366f1"}
                          onChange={(e) => setBrandColor(e.target.value)}
                          disabled={isSaving}
                          aria-label="Pick brand color"
                        />
                        <div
                          className="h-full w-full rounded-md border border-input"
                          style={{ backgroundColor: isValidHex(brandColor) ? brandColor : "#6366f1" }}
                        />
                      </div>
                      <Input
                        placeholder="#6366f1"
                        value={brandColor}
                        onChange={(e) => setBrandColor(e.target.value)}
                        disabled={isSaving}
                        className="font-mono text-sm w-32"
                        maxLength={7}
                        aria-label="Brand color hex code"
                      />
                      {!isValidHex(brandColor) && brandColor.length > 0 && (
                        <span className="text-xs text-destructive">Use 6-digit hex (e.g. #6366f1)</span>
                      )}
                    </div>
                  </div>

                  {/* Tagline */}
                  <div className="space-y-1.5">
                    <Label htmlFor="tagline" className="text-xs font-medium">
                      Tagline
                    </Label>
                    <Input
                      id="tagline"
                      placeholder="We're building the future of work"
                      value={tagline}
                      onChange={(e) => setTagline(e.target.value)}
                      disabled={isSaving}
                      maxLength={160}
                    />
                  </div>

                  {/* About */}
                  <div className="space-y-1.5">
                    <Label htmlFor="about" className="text-xs font-medium">
                      About
                    </Label>
                    <Textarea
                      id="about"
                      placeholder="Tell candidates about your company, culture, and mission…"
                      value={about}
                      onChange={(e) => setAbout(e.target.value)}
                      disabled={isSaving}
                      rows={4}
                      className="resize-none text-sm"
                      maxLength={2000}
                    />
                  </div>

                  {/* Active toggle */}
                  <div className="flex items-center justify-between rounded-lg border border-border p-3">
                    <div className="space-y-0.5">
                      <Label htmlFor="is-active" className="text-sm font-medium cursor-pointer">
                        Publish career page
                      </Label>
                      <p className="text-xs text-muted-foreground">
                        Make your career page publicly accessible to candidates.
                      </p>
                    </div>
                    <Switch
                      id="is-active"
                      checked={isActive}
                      onCheckedChange={setIsActive}
                      disabled={isSaving}
                      aria-label="Publish career page"
                    />
                  </div>

                  {/* Preview link (when active + slug set) */}
                  {isActive && careerPageUrl && (
                    <div className="flex items-center gap-2 rounded-md bg-muted/50 px-3 py-2">
                      <Globe className="h-3.5 w-3.5 text-muted-foreground shrink-0" />
                      <a
                        href={careerPageUrl}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="flex-1 text-xs text-primary truncate hover:underline"
                      >
                        {careerPageUrl}
                      </a>
                      <button
                        onClick={copyUrl}
                        className="shrink-0 text-muted-foreground hover:text-foreground transition-colors"
                        aria-label="Copy career page URL"
                        type="button"
                      >
                        <Copy className="h-3.5 w-3.5" />
                      </button>
                      <a
                        href={careerPageUrl}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="shrink-0 text-muted-foreground hover:text-foreground transition-colors"
                        aria-label="Open in new tab"
                      >
                        <ExternalLink className="h-3.5 w-3.5" />
                      </a>
                    </div>
                  )}

                  {/* Save button */}
                  <div className="flex justify-end pt-1">
                    <Button
                      onClick={handleSave}
                      disabled={isSaving || slugStatus === "taken"}
                      className="gap-1.5"
                    >
                      {isSaving ? (
                        <Loader2 className="h-4 w-4 animate-spin" />
                      ) : (
                        <Save className="h-4 w-4" />
                      )}
                      Save changes
                    </Button>
                  </div>
                </div>
              )}
            </CardContent>
          </Card>

          {/* ---------------------------------------------------------------- */}
          {/* Card 2: Published Jobs                                            */}
          {/* ---------------------------------------------------------------- */}
          <Card className="border border-border/60 shadow-sm">
            <CardHeader className="pb-3">
              <CardTitle className="text-sm font-semibold flex items-center gap-2">
                <Globe className="h-4 w-4 text-primary" />
                Published Jobs
              </CardTitle>
              <CardDescription className="text-xs">
                Toggle which jobs appear on your career page.
              </CardDescription>
            </CardHeader>
            <CardContent className="p-0">
              {jobsLoading ? (
                <JobsSkeleton />
              ) : jobs.length === 0 ? (
                <div className="flex flex-col items-center justify-center py-14 space-y-3 text-center px-4">
                  <div className="rounded-xl bg-muted/50 p-4">
                    <Globe className="h-7 w-7 text-muted-foreground/40" />
                  </div>
                  <div className="space-y-1">
                    <p className="text-sm font-medium text-foreground">No jobs yet</p>
                    <p className="text-sm text-muted-foreground max-w-xs">
                      Create a job posting from the dashboard to list it on your career page.
                    </p>
                  </div>
                </div>
              ) : (
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead className="text-xs">Title</TableHead>
                      <TableHead className="text-xs hidden sm:table-cell">Location</TableHead>
                      <TableHead className="text-xs hidden md:table-cell">Department</TableHead>
                      <TableHead className="text-xs text-right pr-4">Published</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {jobs.map((job) => {
                      const isToggling = togglingJobId === job.id;
                      const published = job.is_published ?? false;
                      return (
                        <TableRow key={job.id}>
                          <TableCell className="text-sm font-medium max-w-[200px]">
                            <div className="truncate" title={job.title ?? ""}>
                              {job.title || <span className="text-muted-foreground italic">Untitled</span>}
                            </div>
                            {job.employment_type && (
                              <span className="text-xs text-muted-foreground">{job.employment_type}</span>
                            )}
                          </TableCell>
                          <TableCell className="text-sm text-muted-foreground hidden sm:table-cell">
                            {job.location || "—"}
                          </TableCell>
                          <TableCell className="text-sm text-muted-foreground hidden md:table-cell">
                            {job.department || "—"}
                          </TableCell>
                          <TableCell className="text-right pr-4">
                            {isToggling ? (
                              <div className="flex justify-end">
                                <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" />
                              </div>
                            ) : (
                              <Switch
                                checked={published}
                                onCheckedChange={() =>
                                  toggleJobPublished.mutate({ jobId: job.id, current: published })
                                }
                                disabled={isToggling}
                                aria-label={`${published ? "Unpublish" : "Publish"} ${job.title ?? "job"}`}
                              />
                            )}
                          </TableCell>
                        </TableRow>
                      );
                    })}
                  </TableBody>
                </Table>
              )}
            </CardContent>
          </Card>
        </StaggerList>
      </main>
    </SidebarLayout>
  );
};

export default CareerSettings;

