// ─── Webhook Management Tab ───────────────────────────────────────────────────

interface WebhookEntry {
  id: string;
  url: string;
  events: string[];
  active: boolean;
}

const WEBHOOK_STORAGE_KEY = "rankora_webhooks";

function loadWebhooks(): WebhookEntry[] {
  try {
    return JSON.parse(localStorage.getItem(WEBHOOK_STORAGE_KEY) || "[]");
  } catch {
    return [];
  }
}

function saveWebhooks(hooks: WebhookEntry[]) {
  localStorage.setItem(WEBHOOK_STORAGE_KEY, JSON.stringify(hooks));
}

const EVENTS = [
  { value: "job.created", label: "Job Created" },
  { value: "ranking.completed", label: "Ranking Completed" },
  { value: "candidate.applied", label: "Candidate Applied" },
  { value: "candidate.rejected", label: "Candidate Rejected" },
  { value: "interview.scheduled", label: "Interview Scheduled" },
  { value: "stage.changed", label: "Stage Changed" },
];

function WebhooksTab() {
  const [webhooks, setWebhooks] = useState<WebhookEntry[]>(loadWebhooks);
  const [newUrl, setNewUrl] = useState("");
  const [newEvents, setNewEvents] = useState<string[]>(["ranking.completed"]);

  const toggleEvent = (value: string) => {
    setNewEvents((prev) =>
      prev.includes(value) ? prev.filter((e) => e !== value) : [...prev, value]
    );
  };

  const addWebhook = () => {
    const url = newUrl.trim();
    if (!url) {
      toast.error("Please enter a webhook URL");
      return;
    }
    try {
      new URL(url);
    } catch {
      toast.error("Please enter a valid URL (must start with https://)");
      return;
    }
    if (newEvents.length === 0) {
      toast.error("Select at least one event to subscribe to");
      return;
    }
    const entry: WebhookEntry = {
      id: crypto.randomUUID(),
      url,
      events: newEvents,
      active: true,
    };
    const updated = [...webhooks, entry];
    setWebhooks(updated);
    saveWebhooks(updated);
    setNewUrl("");
    setNewEvents(["ranking.completed"]);
    toast.success("Webhook endpoint added");
  };

  const removeWebhook = (id: string) => {
    const updated = webhooks.filter((w) => w.id !== id);
    setWebhooks(updated);
    saveWebhooks(updated);
    toast.success("Webhook removed");
  };

  const toggleActive = (id: string) => {
    const updated = webhooks.map((w) =>
      w.id === id ? { ...w, active: !w.active } : w
    );
    setWebhooks(updated);
    saveWebhooks(updated);
  };

  const testWebhook = (wh: WebhookEntry) => {
    toast.promise(
      fetch(wh.url, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          event: "test",
          timestamp: new Date().toISOString(),
          data: { message: "Rankora webhook test payload" },
        }),
      }),
      {
        loading: "Sending test payload...",
        success: "Test payload delivered",
        error: "Failed to reach endpoint — check your URL",
      }
    );
  };

  return (
    <div className="space-y-6">
      {/* Add Webhook */}
      <Card className="border border-border/60 shadow-sm">
        <CardHeader className="pb-3">
          <div className="flex items-center gap-2">
            <Webhook className="h-5 w-5 text-primary" />
            <CardTitle className="text-sm font-semibold">Add Webhook</CardTitle>
          </div>
          <CardDescription>
            Rankora will send a POST request to your URL whenever the selected events occur.
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          {/* URL */}
          <div className="space-y-1.5">
            <Label className="text-xs font-medium">Endpoint URL</Label>
            <Input
              value={newUrl}
              onChange={(e) => setNewUrl(e.target.value)}
              placeholder="https://your-app.com/webhook"
              className="h-9 text-sm font-mono"
              onKeyDown={(e) => e.key === "Enter" && addWebhook()}
            />
          </div>

          {/* Events */}
          <div className="space-y-2">
            <Label className="text-xs font-medium">Events to subscribe</Label>
            <div className="grid grid-cols-2 sm:grid-cols-3 gap-2">
              {EVENTS.map((event) => (
                <label
                  key={event.value}
                  className="flex items-center gap-2 rounded-lg border border-border/60 px-3 py-2 cursor-pointer hover:bg-muted/40 transition-colors"
                >
                  <Checkbox
                    checked={newEvents.includes(event.value)}
                    onCheckedChange={() => toggleEvent(event.value)}
                    className="h-3.5 w-3.5"
                  />
                  <span className="text-xs font-mono text-foreground">{event.value}</span>
                </label>
              ))}
            </div>
          </div>

          <Button size="sm" className="h-9 gap-1.5" onClick={addWebhook}>
            <Plus className="h-3.5 w-3.5" />
            Add Endpoint
          </Button>
        </CardContent>
      </Card>

      {/* Webhook list */}
      {webhooks.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-14 space-y-3">
          <div className="rounded-xl bg-muted/50 p-4">
            <Webhook className="h-6 w-6 text-muted-foreground/40" />
          </div>
          <p className="text-sm font-medium text-foreground">No webhooks yet</p>
          <p className="text-xs text-muted-foreground">Add your first endpoint above to receive real-time events.</p>
        </div>
      ) : (
        <div className="space-y-3">
          <h2 className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
            {webhooks.length} endpoint{webhooks.length !== 1 ? "s" : ""}
          </h2>
          {webhooks.map((wh) => (
            <Card key={wh.id} className="border border-border/60 shadow-sm">
              <CardContent className="p-4 flex items-start gap-3">
                {/* Status dot */}
                <button
                  onClick={() => toggleActive(wh.id)}
                  title={wh.active ? "Active — click to disable" : "Inactive — click to enable"}
                  className="mt-0.5 shrink-0"
                >
                  {wh.active ? (
                    <CheckCircle2 className="h-4 w-4 text-emerald-500" />
                  ) : (
                    <XCircle className="h-4 w-4 text-muted-foreground/40" />
                  )}
                </button>

                {/* URL + events */}
                <div className="flex-1 min-w-0 space-y-1.5">
                  <code className="text-xs font-mono text-foreground block truncate">{wh.url}</code>
                  <div className="flex flex-wrap gap-1">
                    {wh.events.map((ev) => (
                      <Badge key={ev} variant="secondary" className="font-mono text-[10px] px-1.5 py-0">
                        {ev}
                      </Badge>
                    ))}
                  </div>
                </div>

                {/* Actions */}
                <div className="flex items-center gap-1 shrink-0">
                  <Button
                    variant="ghost"
                    size="sm"
                    className="h-7 px-2 text-xs text-muted-foreground hover:text-foreground gap-1"
                    onClick={() => testWebhook(wh)}
                  >
                    <Send className="h-3 w-3" />
                    Test
                  </Button>
                  <Button
                    variant="ghost"
                    size="sm"
                    className="h-7 w-7 p-0 text-muted-foreground hover:text-destructive"
                    onClick={() => removeWebhook(wh.id)}
                  >
                    <Trash2 className="h-3.5 w-3.5" />
                  </Button>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      {/* Payload example */}
      <Card className="border border-border/60 shadow-sm">
        <CardHeader className="pb-2">
          <CardTitle className="text-sm font-semibold">Payload Example</CardTitle>
          <CardDescription>All events follow this JSON structure.</CardDescription>
        </CardHeader>
        <CardContent>
          <CodeBlock
            code={`{
  "event": "ranking.completed",
  "timestamp": "2026-04-09T10:00:00Z",
  "data": {
    "job_id": "3f8a1c2b-...",
    "job_title": "Senior React Developer",
    "total_candidates": 12,
    "top_score": 87
  }
}`}
            language="json"
          />
          <p className="text-xs text-muted-foreground mt-3">
            All webhook payloads are signed with HMAC-SHA256. Verify the{" "}
            <code className="font-mono">X-Rankora-Signature</code> header in your handler.
          </p>
        </CardContent>
      </Card>
    </div>
  );
}

// ─── API Tab ──────────────────────────────────────────────────────────────────

const BASE_URL = "https://zkzontawprihrzpayeam.supabase.co/functions/v1/public-api";

const METHOD_COLORS: Record<string, string> = {
  GET: "bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400 border-emerald-200/60",
  POST: "bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400 border-blue-200/60",
  DELETE: "bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400 border-red-200/60",
  PATCH: "bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400 border-amber-200/60",
};

function MethodBadge({ method }: { method: string }) {
  return (
    <span
      className={`inline-block text-[11px] font-bold font-mono px-1.5 py-0.5 rounded border ${
        METHOD_COLORS[method] ?? "bg-muted text-muted-foreground"
      }`}
    >
      {method}
    </span>
  );
}

function CodeBlock({ code, language = "bash" }: { code: string; language?: string }) {
  const handleCopy = () => {
    navigator.clipboard.writeText(code.trim());
    toast.success("Copied to clipboard");
  };
  return (
    <div className="relative rounded-lg bg-zinc-950 dark:bg-zinc-900 border border-border overflow-hidden">
      <div className="flex items-center justify-between px-4 py-2 border-b border-border/40">
        <span className="text-[11px] font-mono text-zinc-400 uppercase tracking-wider">{language}</span>
        <Button
          variant="ghost"
          size="sm"
          className="h-6 w-6 p-0 text-zinc-400 hover:text-zinc-200"
          onClick={handleCopy}
        >
          <Copy className="h-3 w-3" />
        </Button>
      </div>
      <pre className="px-4 py-3 text-sm font-mono text-zinc-200 overflow-x-auto leading-relaxed whitespace-pre">
        {code.trim()}
      </pre>
    </div>
  );
}

interface EndpointProps {
  method: string;
  path: string;
  description: string;
  params?: { name: string; type: string; required: boolean; description: string }[];
  responseExample?: string;
  requestExample?: string;
}

function Endpoint({ method, path, description, params, responseExample, requestExample }: EndpointProps) {
  const [open, setOpen] = useState(false);
  return (
    <div className="rounded-lg border border-border overflow-hidden">
      <button
        className="w-full flex items-center gap-3 px-4 py-3 hover:bg-muted/40 transition-colors text-left"
        onClick={() => setOpen((v) => !v)}
        aria-expanded={open}
      >
        <MethodBadge method={method} />
        <code className="text-sm font-mono text-foreground flex-1">{path}</code>
        <span className="text-sm text-muted-foreground hidden sm:block">{description}</span>
        <ChevronRight
          className={`h-4 w-4 text-muted-foreground shrink-0 transition-transform ${open ? "rotate-90" : ""}`}
        />
      </button>
      {open && (
        <div className="border-t border-border bg-muted/10 px-4 py-4 space-y-4">
          <p className="text-sm text-muted-foreground">{description}</p>
          {params && params.length > 0 && (
            <div>
              <p className="text-xs font-semibold text-foreground uppercase tracking-wider mb-2">Parameters</p>
              <div className="rounded-lg border border-border overflow-hidden">
                <table className="w-full text-sm">
                  <thead className="bg-muted/50">
                    <tr>
                      <th className="text-left px-3 py-2 text-xs font-semibold text-muted-foreground">Name</th>
                      <th className="text-left px-3 py-2 text-xs font-semibold text-muted-foreground">Type</th>
                      <th className="text-left px-3 py-2 text-xs font-semibold text-muted-foreground">Required</th>
                      <th className="text-left px-3 py-2 text-xs font-semibold text-muted-foreground">Description</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-border">
                    {params.map((p) => (
                      <tr key={p.name}>
                        <td className="px-3 py-2 font-mono text-xs text-foreground">{p.name}</td>
                        <td className="px-3 py-2 font-mono text-xs text-muted-foreground">{p.type}</td>
                        <td className="px-3 py-2">
                          {p.required ? (
                            <Badge variant="destructive" className="text-[10px] px-1.5 py-0">
                              required
                            </Badge>
                          ) : (
                            <span className="text-xs text-muted-foreground">optional</span>
                          )}
                        </td>
                        <td className="px-3 py-2 text-xs text-muted-foreground">{p.description}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}
          {requestExample && (
            <div>
              <p className="text-xs font-semibold text-foreground uppercase tracking-wider mb-2">Request Example</p>
              <CodeBlock code={requestExample} language="bash" />
            </div>
          )}
          {responseExample && (
            <div>
              <p className="text-xs font-semibold text-foreground uppercase tracking-wider mb-2">Response Example</p>
              <CodeBlock code={responseExample} language="json" />
            </div>
          )}
        </div>
      )}
    </div>
  );
}

const ENDPOINTS: EndpointProps[] = [
  {
    method: "GET",
    path: "/jobs",
    description: "List all jobs for your account. Sorted by creation date (newest first).",
    params: [
      { name: "limit", type: "integer", required: false, description: "Max results to return (default: 20, max: 100)" },
      { name: "offset", type: "integer", required: false, description: "Pagination offset (default: 0)" },
    ],
    requestExample: `curl -X GET "${BASE_URL}/jobs?limit=10" \\
  -H "Authorization: Bearer rk_live_YOUR_KEY"`,
    responseExample: `{
  "data": [
    {
      "id": "3f8a1c2b-...",
      "title": "Senior React Developer",
      "status": "completed",
      "created_at": "2026-04-09T10:00:00Z"
    }
  ],
  "offset": 0,
  "limit": 10
}`,
  },
  {
    method: "GET",
    path: "/jobs/:id",
    description: "Get a single job by ID, including the job description and AI analysis.",
    params: [
      { name: "id", type: "uuid", required: true, description: "Job ID (UUID)" },
    ],
    requestExample: `curl -X GET "${BASE_URL}/jobs/3f8a1c2b-..." \\
  -H "Authorization: Bearer rk_live_YOUR_KEY"`,
    responseExample: `{
  "id": "3f8a1c2b-...",
  "title": "Senior React Developer",
  "status": "completed",
  "job_description": "We are looking for...",
  "jd_analysis_json": { "must_haves": [], "nice_to_haves": [] },
  "created_at": "2026-04-09T10:00:00Z"
}`,
  },
  {
    method: "POST",
    path: "/jobs",
    description: "Create a new job posting. Returns the created job record.",
    params: [
      { name: "job_description", type: "string", required: true, description: "Full job description text" },
      { name: "title", type: "string", required: false, description: "Job title (auto-inferred if omitted)" },
    ],
    requestExample: `curl -X POST "${BASE_URL}/jobs" \\
  -H "Authorization: Bearer rk_live_YOUR_KEY" \\
  -H "Content-Type: application/json" \\
  -d '{
    "title": "Senior React Developer",
    "job_description": "We are looking for..."
  }'`,
    responseExample: `{
  "id": "3f8a1c2b-...",
  "title": "Senior React Developer",
  "status": "pending",
  "created_at": "2026-04-09T10:00:00Z"
}`,
  },
  {
    method: "GET",
    path: "/jobs/:id/candidates",
    description: "Get all ranked candidates for a job. Sorted by overall_score descending.",
    params: [
      { name: "id", type: "uuid", required: true, description: "Job ID (UUID)" },
    ],
    requestExample: `curl -X GET "${BASE_URL}/jobs/3f8a1c2b-.../candidates" \\
  -H "Authorization: Bearer rk_live_YOUR_KEY"`,
    responseExample: `{
  "data": [
    {
      "id": "7a2b...",
      "candidate_name": "Jane Smith",
      "filename": "jane_smith.pdf",
      "overall_score": 87,
      "hard_fit": true,
      "confidence": 92,
      "matched_must_haves": ["React", "TypeScript"],
      "missing_must_haves": [],
      "strengths_json": ["5+ years React", "Strong TypeScript"],
      "gaps_json": ["No GraphQL experience"]
    }
  ],
  "job_id": "3f8a1c2b-...",
  "total": 12
}`,
  },
];

function ApiTab() {
  return (
    <div className="space-y-6">
      <p className="text-sm text-muted-foreground">
        Integrate Rankora data into your own tools and workflows using the REST API.
      </p>

      {/* API Keys */}
      <ApiKeysCard />

      {/* Base URL */}
      <Card className="border border-border/60 shadow-sm">
        <CardHeader className="pb-2">
          <div className="flex items-center gap-2">
            <Globe className="h-4 w-4 text-primary" />
            <CardTitle className="text-sm font-semibold">Base URL</CardTitle>
          </div>
        </CardHeader>
        <CardContent>
          <CodeBlock code={BASE_URL} language="url" />
        </CardContent>
      </Card>

      {/* Authentication */}
      <Card className="border border-border/60 shadow-sm">
        <CardHeader className="pb-2">
          <div className="flex items-center gap-2">
            <Key className="h-4 w-4 text-primary" />
            <CardTitle className="text-sm font-semibold">Authentication</CardTitle>
          </div>
          <CardDescription>All API requests require a valid API key in the Authorization header.</CardDescription>
        </CardHeader>
        <CardContent className="space-y-3">
          <CodeBlock code={`Authorization: Bearer rk_live_YOUR_KEY_HERE`} language="http" />
          <div className="rounded-lg bg-amber-50 dark:bg-amber-900/20 border border-amber-200 dark:border-amber-800 px-4 py-3">
            <p className="text-xs text-amber-800 dark:text-amber-200">
              Never expose your API key in client-side code. Always make requests from your backend server or a trusted environment.
            </p>
          </div>
        </CardContent>
      </Card>

      {/* Rate Limits */}
      <Card className="border border-border/60 shadow-sm">
        <CardHeader className="pb-2">
          <CardTitle className="text-sm font-semibold">Rate Limits</CardTitle>
          <CardDescription>All API keys are subject to the following rate limits.</CardDescription>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-3 gap-4">
            {[
              { label: "Requests", value: "100/min", note: "Per API key" },
              { label: "Jobs created", value: "50/day", note: "Via API" },
              { label: "Candidates", value: "500/req", note: "Per response" },
            ].map((item) => (
              <div key={item.label} className="rounded-lg border border-border bg-muted/30 px-4 py-3 text-center">
                <p className="text-lg font-bold tabular-nums text-foreground">{item.value}</p>
                <p className="text-xs font-medium text-foreground mt-0.5">{item.label}</p>
                <p className="text-[11px] text-muted-foreground">{item.note}</p>
              </div>
            ))}
          </div>
          <p className="text-xs text-muted-foreground mt-3">
            When rate-limited you receive HTTP 429. Retry after the{" "}
            <code className="font-mono">Retry-After</code> header value (seconds).
          </p>
        </CardContent>
      </Card>

      {/* Error Codes */}
      <Card className="border border-border/60 shadow-sm">
        <CardHeader className="pb-2">
          <CardTitle className="text-sm font-semibold">Error Codes</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="rounded-lg border border-border overflow-hidden">
            <table className="w-full text-sm">
              <thead className="bg-muted/50">
                <tr>
                  <th className="text-left px-3 py-2 text-xs font-semibold text-muted-foreground">Status</th>
                  <th className="text-left px-3 py-2 text-xs font-semibold text-muted-foreground">Code</th>
                  <th className="text-left px-3 py-2 text-xs font-semibold text-muted-foreground">Meaning</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-border text-xs">
                {[
                  { status: "400", code: "bad_request", meaning: "Invalid JSON or missing required fields" },
                  { status: "400", code: "validation_error", meaning: "Field validation failed" },
                  { status: "401", code: "unauthorized", meaning: "Missing, invalid, or revoked API key" },
                  { status: "404", code: "not_found", meaning: "Resource not found or access denied" },
                  { status: "405", code: "method_not_allowed", meaning: "HTTP method not supported for this route" },
                  { status: "429", code: "rate_limited", meaning: "Too many requests — slow down" },
                  { status: "500", code: "error", meaning: "Internal server error" },
                ].map((row) => (
                  <tr key={row.code}>
                    <td className="px-3 py-2 font-mono">{row.status}</td>
                    <td className="px-3 py-2 font-mono text-muted-foreground">{row.code}</td>
                    <td className="px-3 py-2 text-muted-foreground">{row.meaning}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </CardContent>
      </Card>

      {/* Endpoints */}
      <div>
        <h2 className="text-sm font-semibold text-foreground mb-3">Endpoints</h2>
        <div className="space-y-2">
          {ENDPOINTS.map((ep) => (
            <Endpoint key={`${ep.method}-${ep.path}`} {...ep} />
          ))}
        </div>
      </div>

      {/* 5-Minute Quickstart */}
      <Card className="border border-border/60 shadow-sm">
        <CardHeader className="pb-2">
          <div className="flex items-center gap-2">
            <BookOpen className="h-4 w-4 text-primary" />
            <CardTitle className="text-sm font-semibold">5-Minute Quickstart</CardTitle>
          </div>
          <CardDescription>Get candidate data from Rankora into your app in under 5 minutes.</CardDescription>
        </CardHeader>
        <CardContent className="space-y-5">
          {[
            {
              step: "1",
              title: "Generate an API key",
              description:
                'Go to the API Keys section above and click "Generate Key". Copy the key — it\'s only shown in full once.',
            },
            {
              step: "2",
              title: "List your jobs",
              description: "Make your first request to verify authentication:",
              code: {
                bash: `curl -X GET "${BASE_URL}/jobs" \\
  -H "Authorization: Bearer rk_live_YOUR_KEY"`,
                javascript: `const res = await fetch("${BASE_URL}/jobs", {
  headers: { "Authorization": "Bearer rk_live_YOUR_KEY" }
});
const { data } = await res.json();
console.log(data); // [{ id, title, status, created_at }]`,
                python: `import requests

response = requests.get(
    "${BASE_URL}/jobs",
    headers={"Authorization": "Bearer rk_live_YOUR_KEY"}
)
jobs = response.json()["data"]
print(jobs)`,
              },
            },
            {
              step: "3",
              title: "Get candidates for a job",
              description: "Pick a job ID from step 2 and fetch its ranked candidates:",
              code: {
                bash: `curl -X GET "${BASE_URL}/jobs/JOB_ID/candidates" \\
  -H "Authorization: Bearer rk_live_YOUR_KEY"`,
                javascript: `const res = await fetch("${BASE_URL}/jobs/JOB_ID/candidates", {
  headers: { "Authorization": "Bearer rk_live_YOUR_KEY" }
});
const { data } = await res.json();
data.forEach(c => console.log(c.candidate_name, c.overall_score));`,
                python: `response = requests.get(
    f"${BASE_URL}/jobs/JOB_ID/candidates",
    headers={"Authorization": "Bearer rk_live_YOUR_KEY"}
)
candidates = response.json()["data"]
for c in candidates:
    print(c["candidate_name"], c["overall_score"])`,
              },
            },
          ].map(({ step, title, description, code }) => (
            <div key={step} className="space-y-3">
              <div className="flex items-start gap-3">
                <span className="h-6 w-6 rounded-full bg-primary text-primary-foreground text-xs font-bold flex items-center justify-center shrink-0 mt-0.5">
                  {step}
                </span>
                <div>
                  <h3 className="text-sm font-medium text-foreground">{title}</h3>
                  <p className="text-sm text-muted-foreground mt-0.5">{description}</p>
                </div>
              </div>
              {code && (
                <div className="ml-9">
                  <Tabs defaultValue="bash">
                    <TabsList className="h-7 mb-2">
                      <TabsTrigger value="bash" className="text-xs h-6">
                        cURL
                      </TabsTrigger>
                      <TabsTrigger value="javascript" className="text-xs h-6">
                        JavaScript
                      </TabsTrigger>
                      <TabsTrigger value="python" className="text-xs h-6">
                        Python
                      </TabsTrigger>
                    </TabsList>
                    <TabsContent value="bash">
                      <CodeBlock code={code.bash} language="bash" />
                    </TabsContent>
                    <TabsContent value="javascript">
                      <CodeBlock code={code.javascript} language="javascript" />
                    </TabsContent>
                    <TabsContent value="python">
                      <CodeBlock code={code.python} language="python" />
                    </TabsContent>
                  </Tabs>
                </div>
              )}
            </div>
          ))}
        </CardContent>
      </Card>
    </div>
  );
}

// ─── Main Page ─────────────────────────────────────────────────────────────────

const Integrations = () => {
  const [search, setSearch] = useState("");

  const filtered = useMemo(() => {
    const q = search.toLowerCase().trim();
    const base = q
      ? INTEGRATIONS.filter(
          (i) => i.name.toLowerCase().includes(q) || i.description.toLowerCase().includes(q)
        )
      : INTEGRATIONS;

    return [...base].sort((a, b) => STATUS_ORDER[a.status] - STATUS_ORDER[b.status]);
  }, [search]);

  return (
    <SidebarLayout>
      <main className="w-full px-6 sm:px-8 lg:px-10 py-8">
        {/* Page header */}
        <div className="mb-2">
          <h1 className="text-2xl font-semibold tracking-tight text-foreground">Integrations</h1>
          <p className="text-sm text-muted-foreground mt-1">
            Connect your tools, manage API access, and configure webhooks.
          </p>
        </div>

        <Tabs defaultValue="integrations">
          <TabsList className="mt-6 mb-6">
            <TabsTrigger value="integrations">Integrations</TabsTrigger>
            <TabsTrigger value="webhooks">Webhooks</TabsTrigger>
            <TabsTrigger value="api">API</TabsTrigger>
          </TabsList>

          {/* ── Integrations tab ── */}
          <TabsContent value="integrations" className="space-y-5">
            {/* Search */}
            <div className="relative max-w-sm">
              <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-muted-foreground pointer-events-none" />
              <Input
                placeholder="Search integrations..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                className="pl-8 h-9 text-sm"
              />
            </div>

            {filtered.length === 0 ? (
              <div className="flex flex-col items-center justify-center py-16 space-y-3">
                <div className="rounded-xl bg-muted/50 p-4">
                  <Search className="h-6 w-6 text-muted-foreground/50" />
                </div>
                <p className="text-sm font-medium">No integrations found</p>
                <p className="text-xs text-muted-foreground">Try a different search term</p>
              </div>
            ) : (
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
                {filtered.map((integ) => (
                  <IntegrationCard key={integ.id} integration={integ} />
                ))}
              </div>
            )}
          </TabsContent>

          {/* ── Webhooks tab ── */}
          <TabsContent value="webhooks">
            <WebhooksTab />
          </TabsContent>

          {/* ── API tab ── */}
          <TabsContent value="api">
            <ApiTab />
          </TabsContent>
        </Tabs>
      </main>
    </SidebarLayout>
  );
};

export default Integrations;

