// ─── Integration Card (horizontal) ───────────────────────────────────────────

const IntegrationCard = ({ integration }: { integration: Integration }) => {
  const isConnected = integration.status === "connected";
  const isAvailable = integration.status === "available";
  const isSoon = integration.status === "coming_soon";

  const handleAction = () => {
    if (isConnected) {
      toast.info(`${integration.name} — configuration coming soon`);
    } else if (isAvailable) {
      toast.info(`${integration.name} setup guide coming soon`);
    }
  };

  return (
    <Card
      className={cn(
        "border border-border/60 shadow-sm transition-all hover:shadow-md",
        isConnected && "border-primary/20",
        isSoon && "opacity-50"
      )}
    >
      <CardContent className="p-5 flex items-start gap-4">
        {/* Icon */}
        <div className={cn("h-10 w-10 rounded-xl flex items-center justify-center shrink-0", integration.iconBg)}>
          {integration.icon}
        </div>

        {/* Text + badges */}
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 flex-wrap">
            <p className="text-sm font-semibold text-foreground">{integration.name}</p>
            {isConnected && (
              <Badge className="bg-emerald-50 text-emerald-700 border border-emerald-200 hover:bg-emerald-50 text-[10px] dark:bg-emerald-900/30 dark:text-emerald-400 dark:border-emerald-800">
                Connected
              </Badge>
            )}
            {isAvailable && (
              <Badge variant="outline" className="bg-blue-50 text-blue-700 border-blue-200 text-[10px] dark:bg-blue-900/30 dark:text-blue-400 dark:border-blue-800">
                Available
              </Badge>
            )}
            {isSoon && (
              <Badge variant="secondary" className="text-[10px]">
                Soon
              </Badge>
            )}
          </div>
          <p className="text-xs text-muted-foreground mt-1 leading-relaxed">{integration.description}</p>
        </div>

        {/* Action button */}
        {isConnected && (
          <Button
            variant="ghost"
            size="sm"
            className="h-8 text-xs shrink-0 text-muted-foreground"
            onClick={handleAction}
          >
            Configure
          </Button>
        )}
        {isAvailable && (
          <Button
            variant="outline"
            size="sm"
            className="h-8 text-xs shrink-0"
            onClick={handleAction}
          >
            Connect
          </Button>
        )}
      </CardContent>
    </Card>
  );
};

// ─── Webhook Management Tab ───────────────────────────────────────────────────

interface WebhookEntry {
  id: string;
  url: string;
  events: string[];
  active: boolean;
}

const WEBHOOK_STORAGE_KEY = "rankora_webhooks";

function loadWebhooks(): WebhookEntry[] {
  try {
    return JSON.parse(localStorage.getItem(WEBHOOK_STORAGE_KEY) || "[]");
  } catch {
    return [];
  }
}

function saveWebhooks(hooks: WebhookEntry[]) {
  localStorage.setItem(WEBHOOK_STORAGE_KEY, JSON.stringify(hooks));
}

const EVENTS = [
  { value: "job.created", label: "Job Created" },
  { value: "ranking.completed", label: "Ranking Completed" },
  { value: "candidate.applied", label: "Candidate Applied" },
  { value: "candidate.rejected", label: "Candidate Rejected" },
  { value: "interview.scheduled", label: "Interview Scheduled" },
  { value: "stage.changed", label: "Stage Changed" },
];

function WebhooksTab() {
  const [webhooks, setWebhooks] = useState<WebhookEntry[]>(loadWebhooks);
  const [newUrl, setNewUrl] = useState("");
  const [newEvents, setNewEvents] = useState<string[]>(["ranking.completed"]);

  const toggleEvent = (value: string) => {
    setNewEvents((prev) =>
      prev.includes(value) ? prev.filter((e) => e !== value) : [...prev, value]
    );
  };

  const addWebhook = () => {
    const url = newUrl.trim();
    if (!url) {
      toast.error("Please enter a webhook URL");
      return;
    }
    try {
      new URL(url);
    } catch {
      toast.error("Please enter a valid URL (must start with https://)");
      return;
    }
    if (newEvents.length === 0) {
      toast.error("Select at least one event to subscribe to");
      return;
    }
    const entry: WebhookEntry = {
      id: crypto.randomUUID(),
      url,
      events: newEvents,
      active: true,
    };
    const updated = [...webhooks, entry];
    setWebhooks(updated);
    saveWebhooks(updated);
    setNewUrl("");
    setNewEvents(["ranking.completed"]);
    toast.success("Webhook endpoint added");
  };

  const removeWebhook = (id: string) => {
    const updated = webhooks.filter((w) => w.id !== id);
    setWebhooks(updated);
    saveWebhooks(updated);
    toast.success("Webhook removed");
  };

  const toggleActive = (id: string) => {
    const updated = webhooks.map((w) =>
      w.id === id ? { ...w, active: !w.active } : w
    );
    setWebhooks(updated);
    saveWebhooks(updated);
  };

  const testWebhook = (wh: WebhookEntry) => {
    toast.promise(
      fetch(wh.url, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          event: "test",
          timestamp: new Date().toISOString(),
          data: { message: "Rankora webhook test payload" },
        }),
      }),
      {
        loading: "Sending test payload...",
        success: "Test payload delivered",
        error: "Failed to reach endpoint — check your URL",
      }
    );
  };

  return (
    <div className="space-y-6">
      {/* Add Webhook */}
      <Card className="border border-border/60 shadow-sm">
        <CardHeader className="pb-3">
          <div className="flex items-center gap-2">
            <Webhook className="h-5 w-5 text-primary" />
            <CardTitle className="text-sm font-semibold">Add Webhook</CardTitle>
          </div>
          <CardDescription>
            Rankora will send a POST request to your URL whenever the selected events occur.
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          {/* URL */}
          <div className="space-y-1.5">
            <Label className="text-xs font-medium">Endpoint URL</Label>
            <Input
              value={newUrl}
              onChange={(e) => setNewUrl(e.target.value)}
              placeholder="https://your-app.com/webhook"
              className="h-9 text-sm font-mono"
              onKeyDown={(e) => e.key === "Enter" && addWebhook()}
            />
          </div>

          {/* Events */}
          <div className="space-y-2">
            <Label className="text-xs font-medium">Events to subscribe</Label>
            <div className="grid grid-cols-2 sm:grid-cols-3 gap-2">
              {EVENTS.map((event) => (
                <label
                  key={event.value}
                  className="flex items-center gap-2 rounded-lg border border-border/60 px-3 py-2 cursor-pointer hover:bg-muted/40 transition-colors"
                >
                  <Checkbox
                    checked={newEvents.includes(event.value)}
                    onCheckedChange={() => toggleEvent(event.value)}
                    className="h-3.5 w-3.5"
                  />
                  <span className="text-xs font-mono text-foreground">{event.value}</span>
                </label>
              ))}
            </div>
          </div>

          <Button size="sm" className="h-9 gap-1.5" onClick={addWebhook}>
            <Plus className="h-3.5 w-3.5" />
            Add Endpoint
          </Button>
        </CardContent>
      </Card>

      {/* Webhook list */}
      {webhooks.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-14 space-y-3">
          <div className="rounded-xl bg-muted/50 p-4">
            <Webhook className="h-6 w-6 text-muted-foreground/40" />
          </div>
          <p className="text-sm font-medium text-foreground">No webhooks yet</p>
          <p className="text-xs text-muted-foreground">Add your first endpoint above to receive real-time events.</p>
        </div>
      ) : (
        <div className="space-y-3">
          <h2 className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
            {webhooks.length} endpoint{webhooks.length !== 1 ? "s" : ""}
          </h2>
          {webhooks.map((wh) => (
            <Card key={wh.id} className="border border-border/60 shadow-sm">
              <CardContent className="p-4 flex items-start gap-3">
                {/* Status dot */}
                <button
                  onClick={() => toggleActive(wh.id)}
                  title={wh.active ? "Active — click to disable" : "Inactive — click to enable"}
                  className="mt-0.5 shrink-0"
                >
                  {wh.active ? (
                    <CheckCircle2 className="h-4 w-4 text-emerald-500" />
                  ) : (
                    <XCircle className="h-4 w-4 text-muted-foreground/40" />
                  )}
                </button>

                {/* URL + events */}
                <div className="flex-1 min-w-0 space-y-1.5">
                  <code className="text-xs font-mono text-foreground block truncate">{wh.url}</code>
                  <div className="flex flex-wrap gap-1">
                    {wh.events.map((ev) => (
                      <Badge key={ev} variant="secondary" className="font-mono text-[10px] px-1.5 py-0">
                        {ev}
                      </Badge>
                    ))}
                  </div>
                </div>

                {/* Actions */}
                <div className="flex items-center gap-1 shrink-0">
                  <Button
                    variant="ghost"
                    size="sm"
                    className="h-7 px-2 text-xs text-muted-foreground hover:text-foreground gap-1"
                    onClick={() => testWebhook(wh)}
                  >
                    <Send className="h-3 w-3" />
                    Test
                  </Button>
                  <Button
                    variant="ghost"
                    size="sm"
                    className="h-7 w-7 p-0 text-muted-foreground hover:text-destructive"
                    onClick={() => removeWebhook(wh.id)}
                  >
                    <Trash2 className="h-3.5 w-3.5" />
                  </Button>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      {/* Payload example */}
      <Card className="border border-border/60 shadow-sm">
        <CardHeader className="pb-2">
          <CardTitle className="text-sm font-semibold">Payload Example</CardTitle>
          <CardDescription>All events follow this JSON structure.</CardDescription>
        </CardHeader>
        <CardContent>
          <CodeBlock
            code={`{
  "event": "ranking.completed",
  "timestamp": "2026-04-09T10:00:00Z",
  "data": {
    "job_id": "3f8a1c2b-...",
    "job_title": "Senior React Developer",
    "total_candidates": 12,
    "top_score": 87
  }
}`}
            language="json"
          />
          <p className="text-xs text-muted-foreground mt-3">
            All webhook payloads are signed with HMAC-SHA256. Verify the{" "}
            <code className="font-mono">X-Rankora-Signature</code> header in your handler.
          </p>
        </CardContent>
      </Card>
    </div>
  );
}

