  DELETE: "bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400 border-red-200/60",
  PATCH: "bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400 border-amber-200/60",
};

function MethodBadge({ method }: { method: string }) {
  return (
    <span
      className={`inline-block text-[11px] font-bold font-mono px-1.5 py-0.5 rounded border ${
        METHOD_COLORS[method] ?? "bg-muted text-muted-foreground"
      }`}
    >
      {method}
    </span>
  );
}

function CodeBlock({ code, language = "bash" }: { code: string; language?: string }) {
  const handleCopy = () => {
    navigator.clipboard.writeText(code.trim());
    toast.success("Copied to clipboard");
  };
  return (
    <div className="relative rounded-lg bg-zinc-950 dark:bg-zinc-900 border border-border overflow-hidden">
      <div className="flex items-center justify-between px-4 py-2 border-b border-border/40">
        <span className="text-[11px] font-mono text-zinc-400 uppercase tracking-wider">{language}</span>
        <Button
          variant="ghost"
          size="sm"
          className="h-6 w-6 p-0 text-zinc-400 hover:text-zinc-200"
          onClick={handleCopy}
        >
          <Copy className="h-3 w-3" />
        </Button>
      </div>
      <pre className="px-4 py-3 text-sm font-mono text-zinc-200 overflow-x-auto leading-relaxed whitespace-pre">
        {code.trim()}
      </pre>
    </div>
  );
}

interface EndpointProps {
  method: string;
  path: string;
  description: string;
  params?: { name: string; type: string; required: boolean; description: string }[];
  responseExample?: string;
  requestExample?: string;
}

function Endpoint({ method, path, description, params, responseExample, requestExample }: EndpointProps) {
  const [open, setOpen] = useState(false);
  return (
    <div className="rounded-lg border border-border overflow-hidden">
      <button
        className="w-full flex items-center gap-3 px-4 py-3 hover:bg-muted/40 transition-colors text-left"
        onClick={() => setOpen((v) => !v)}
        aria-expanded={open}
      >
        <MethodBadge method={method} />
        <code className="text-sm font-mono text-foreground flex-1">{path}</code>
        <span className="text-sm text-muted-foreground hidden sm:block">{description}</span>
        <ChevronRight
          className={`h-4 w-4 text-muted-foreground shrink-0 transition-transform ${open ? "rotate-90" : ""}`}
        />
      </button>
      {open && (
        <div className="border-t border-border bg-muted/10 px-4 py-4 space-y-4">
          <p className="text-sm text-muted-foreground">{description}</p>
          {params && params.length > 0 && (
            <div>
              <p className="text-xs font-semibold text-foreground uppercase tracking-wider mb-2">Parameters</p>
              <div className="rounded-lg border border-border overflow-hidden">
                <table className="w-full text-sm">
                  <thead className="bg-muted/50">
                    <tr>
                      <th className="text-left px-3 py-2 text-xs font-semibold text-muted-foreground">Name</th>
                      <th className="text-left px-3 py-2 text-xs font-semibold text-muted-foreground">Type</th>
                      <th className="text-left px-3 py-2 text-xs font-semibold text-muted-foreground">Required</th>
                      <th className="text-left px-3 py-2 text-xs font-semibold text-muted-foreground">Description</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-border">
                    {params.map((p) => (
                      <tr key={p.name}>
                        <td className="px-3 py-2 font-mono text-xs text-foreground">{p.name}</td>
                        <td className="px-3 py-2 font-mono text-xs text-muted-foreground">{p.type}</td>
                        <td className="px-3 py-2">
                          {p.required ? (
                            <Badge variant="destructive" className="text-[10px] px-1.5 py-0">
                              required
                            </Badge>
                          ) : (
                            <span className="text-xs text-muted-foreground">optional</span>
                          )}
                        </td>
                        <td className="px-3 py-2 text-xs text-muted-foreground">{p.description}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}
          {requestExample && (
            <div>
              <p className="text-xs font-semibold text-foreground uppercase tracking-wider mb-2">Request Example</p>
              <CodeBlock code={requestExample} language="bash" />
            </div>
          )}
          {responseExample && (
            <div>
              <p className="text-xs font-semibold text-foreground uppercase tracking-wider mb-2">Response Example</p>
              <CodeBlock code={responseExample} language="json" />
            </div>
          )}
        </div>
      )}
    </div>
  );
}

const ENDPOINTS: EndpointProps[] = [
  {
