import { Badge } from "@/components/ui/badge";
import { CheckCircle2, XCircle } from "lucide-react";
import type { Result } from "@/pages/Index";

interface StrengthsGapsPanelProps {
  result: Result;
}

const StrengthsGapsPanel = ({ result: r }: StrengthsGapsPanelProps) => {
  const strengths = Array.isArray(r.strengths_json) ? r.strengths_json.map(String) : [];
  const gaps = Array.isArray(r.gaps_json) ? r.gaps_json.map(String) : [];

  if (strengths.length === 0 && gaps.length === 0) return null;

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
      {strengths.length > 0 && (
        <div className="rounded-xl border border-border overflow-hidden">
          <div className="bg-emerald-500 px-4 py-2.5 flex items-center gap-2">
            <CheckCircle2 className="h-4 w-4 text-white" />
            <span className="text-sm font-semibold text-white">Strengths</span>
            <span className="ml-auto text-xs font-medium text-white/70 bg-white/20 px-2 py-0.5 rounded-full">{strengths.length}</span>
          </div>
          <div className="p-4 space-y-2.5 bg-card">
            {strengths.map((s, i) => (
              <div key={i} className="flex items-start gap-2.5 text-sm leading-snug">
                <span className="mt-2 h-1.5 w-1.5 rounded-full bg-emerald-500 shrink-0" />
                <span className="text-foreground">{s}</span>
              </div>
            ))}
          </div>
        </div>
      )}
      {gaps.length > 0 && (
        <div className="rounded-xl border border-border overflow-hidden">
          <div className="bg-red-500 px-4 py-2.5 flex items-center gap-2">
            <XCircle className="h-4 w-4 text-white" />
            <span className="text-sm font-semibold text-white">Gaps</span>
            <span className="ml-auto text-xs font-medium text-white/70 bg-white/20 px-2 py-0.5 rounded-full">{gaps.length}</span>
          </div>
          <div className="p-4 space-y-2.5 bg-card">
            {gaps.map((g, i) => (
              <div key={i} className="flex items-start gap-2.5 text-sm leading-snug">
                <span className="mt-2 h-1.5 w-1.5 rounded-full bg-red-500 shrink-0" />
                <span className="text-foreground">{g}</span>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export default StrengthsGapsPanel;

