import { useState } from "react";
import { ChevronDown, ChevronUp, MessageSquare } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import type { Result } from "@/pages/Index";

interface InterviewQuestionsPanelProps {
  result: Result;
}

const InterviewQuestionsPanel = ({ result: r }: InterviewQuestionsPanelProps) => {
  const [isOpen, setIsOpen] = useState(false);
  const questions = r.interview_questions;

  if (!questions || !Array.isArray(questions) || questions.length === 0) return null;

  const remaining = questions.slice(1);
  if (remaining.length === 0) return null;

  return (
    <div className="rounded-xl border border-border overflow-hidden">
      <button
        className="w-full px-4 py-3 flex items-center gap-2.5 bg-foreground/[0.03] hover:bg-foreground/[0.06] transition-colors"
        onClick={() => setIsOpen(!isOpen)}
      >
        <MessageSquare className="h-4 w-4 text-primary" />
        <span className="text-sm font-semibold text-foreground">Interview Questions</span>
        <Badge variant="secondary" className="text-[11px] h-5">{remaining.length}</Badge>
        <div className="ml-auto">
          {isOpen ? <ChevronUp className="h-4 w-4 text-muted-foreground" /> : <ChevronDown className="h-4 w-4 text-muted-foreground" />}
        </div>
      </button>
      {isOpen && (
        <div className="border-t border-border px-4 py-4 space-y-3 bg-card">
          {remaining.map((q: any, i: number) => (
            <div key={i} className="flex gap-3 text-sm leading-relaxed">
              <span className="h-6 w-6 rounded-full bg-primary/10 text-primary text-xs font-bold flex items-center justify-center shrink-0">{i + 2}</span>
              <span className="text-foreground pt-0.5">{typeof q === "string" ? q : String(q)}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default InterviewQuestionsPanel;

