              ))}
            </div>
          )}
          <button
            className="w-full px-4 py-2 flex items-center justify-center gap-1.5 text-xs font-medium text-muted-foreground hover:text-foreground bg-muted/30 hover:bg-muted/50 transition-colors border-t border-border"
            onClick={() => setIsOpen(!isOpen)}
          >
            {isOpen ? (
