                          <div key={b.label} className="rounded-lg border border-border p-3 text-center transition-colors hover:border-primary/30">
                            <p className="text-lg font-bold tabular-nums" style={{ color: b.value >= 70 ? "#22c55e" : b.value >= 40 ? "#f59e0b" : "#ef4444" }}>{Math.round(b.value)}</p>
                            <p className="text-[11px] text-muted-foreground font-medium mt-0.5">{b.label}</p>
                          </div>
                        ))}
                      </div>
                    );
                  })()}

                  {/* Duplicate alert */}
                  {duplicates && duplicates.length > 0 && (
                    <div className="rounded-lg border border-orange-200 bg-orange-50 dark:border-orange-700 dark:bg-orange-900/10 p-3 flex items-start gap-2.5">
                      <Layers className="h-4 w-4 text-orange-500 shrink-0 mt-0.5" />
                      <div className="flex-1 min-w-0">
                        <p className="text-sm font-medium text-orange-700 dark:text-orange-400">
                          Applied to {duplicates.length} other job{duplicates.length !== 1 ? "s" : ""}
                        </p>
                        <p className="text-xs text-orange-600/80 dark:text-orange-400/70 mt-0.5 truncate">
                          {duplicates.slice(0, 2).map((d) => d.duplicate_job_title).join(", ")}
                          {duplicates.length > 2 && ` +${duplicates.length - 2} more`}
                        </p>
                      </div>
                      <button
                        className="text-xs text-orange-600 dark:text-orange-400 underline underline-offset-2 hover:no-underline shrink-0 mt-0.5"
                        onClick={() => setDuplicateDialogOpen(true)}
                      >
                        View
                      </button>
                    </div>
                  )}

                  {/* Must-have skills with progress */}
                  {(() => {
                    const matched = (r.matched_must_haves as string[] | undefined) ?? [];
                    const missing = (r.missing_must_haves as string[] | undefined) ?? [];
                    const total = matched.length + missing.length;
                    if (!total) return null;
                    return (
                      <div>
                        <div className="flex items-center justify-between mb-2">
                          <p className="text-[11px] font-semibold text-muted-foreground uppercase tracking-wider">
                            Must-Have Skills
                          </p>
                          <span className="text-xs font-medium tabular-nums text-muted-foreground">
                            {matched.length}/{total} matched
                          </span>
                        </div>
                        {/* Progress bar */}
                        <div className="h-2 rounded-full bg-muted overflow-hidden mb-3">
                          <div
                            className="h-full rounded-full bg-emerald-500 transition-all duration-500"
                            style={{ width: `${(matched.length / total) * 100}%` }}
                          />
                        </div>
                        <div className="flex flex-wrap gap-2">
                          {matched.map((s) => (
                            <span
                              key={s}
                              className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium bg-emerald-50 text-emerald-700 border border-emerald-200 dark:bg-emerald-950/40 dark:text-emerald-400 dark:border-emerald-800"
                            >
                              <CheckCircle2 className="h-3 w-3" />
                              {s}
                            </span>
                          ))}
                          {missing.map((s) => (
                            <span
                              key={s}
                              className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium bg-red-50 text-red-700 border border-red-200 dark:bg-red-950/40 dark:text-red-400 dark:border-red-800"
                            >
                              <XCircle className="h-3 w-3" />
                              {s}
                            </span>
                          ))}
                        </div>
                      </div>
                    );
                  })()}

                  <StrengthsGapsPanel result={r} />
                  <InterviewQuestionsPanel result={r} />
                  {(onAddTag || onRemoveTag) && (
                    <CandidateTagInput
                      resumeId={r.resume_id}
                      tags={tags}
                      onAdd={onAddTag ?? (() => {})}
                      onRemove={onRemoveTag ?? (() => {})}
                    />
                  )}
                </div>
              </ScrollArea>
            </TabsContent>

            {/* ── Analysis tab ──────────────────────────────────────────── */}
            <TabsContent value="analysis" className="flex-1 min-h-0 mt-0">
              <ScrollArea className="h-full">
                <div className="px-5 py-5 space-y-5">
                  {/* Section: AI Summary */}
                  <div>
                    <p className="text-[11px] font-semibold text-muted-foreground uppercase tracking-wider pb-2 border-b border-border/30 mb-3">AI Summary</p>
                    <CandidateSummaryCard
                      result={r}
                      candidateName={candidateName}
                      compact={false}
                    />
                  </div>

                  {/* Section: Job Alignment */}
                  <div>
                    <p className="text-[11px] font-semibold text-muted-foreground uppercase tracking-wider pb-2 border-b border-border/30 mb-3">Job Alignment</p>
                    <JDAlignedPanel result={r} />
                  </div>

                  {/* Section: Skills Breakdown */}
                  <div>
                    <p className="text-[11px] font-semibold text-muted-foreground uppercase tracking-wider pb-2 border-b border-border/30 mb-3">Skills Breakdown</p>
                    <SkillsDetailPanel result={r} />
                  </div>

                  {/* Section: Background */}
                  <div>
                    <p className="text-[11px] font-semibold text-muted-foreground uppercase tracking-wider pb-2 border-b border-border/30 mb-3">Background</p>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      <ExperiencePanel
                        parsedJson={r.parsed_json}
                        matchedMustHaves={r.matched_must_haves as string[]}
                      />
                      <EducationPanel
                        parsedJson={r.parsed_json}
                        matchedMustHaves={r.matched_must_haves}
                        missingMustHaves={r.missing_must_haves}
                      />
                    </div>
                  </div>

                  {/* Section: Authenticity */}
                  <div>
                    <p className="text-[11px] font-semibold text-muted-foreground uppercase tracking-wider pb-2 border-b border-border/30 mb-3">
                      Authenticity Analysis
                    </p>
                    <AuthenticityReport
                      resumeId={r.resume_id}
                      initialData={(r as any).authenticity_json ?? null}
                    />
                  </div>
                </div>
              </ScrollArea>
            </TabsContent>

            {/* ── Team tab ──────────────────────────────────────────────── */}
            <TabsContent value="team" className="flex-1 min-h-0 mt-0">
              <ScrollArea className="h-full">
                <div className="px-5 py-5 space-y-5">
                  {teamMembers.length > 0 && (
                    <div>
                      <p className="text-[11px] font-semibold text-muted-foreground uppercase tracking-wider pb-2 border-b border-border/30 mb-3">
                        Assignee
                      </p>
                      <AssigneeSelector
                        resumeId={r.resume_id}
                        assignedTo={(r as any).assigned_to ?? null}
                        members={teamMembers}
                        onAssigned={(userId) => onAssigned?.(r.resume_id, userId)}
                      />
                    </div>
                  )}
                  {jobId && (
                    <div>
                      <p className="text-[11px] font-semibold text-muted-foreground uppercase tracking-wider pb-2 border-b border-border/30 mb-3">
                        Notes
                      </p>
                      <CandidateNotesPanel resumeId={r.resume_id} jobId={jobId} />
                    </div>
                  )}
                  {jobId && teamId && (
                    <div>
                      <p className="text-[11px] font-semibold text-muted-foreground uppercase tracking-wider pb-2 border-b border-border/30 mb-3">
                        Evaluations
                      </p>
                      <ScorecardSummary
                        resumeId={r.resume_id}
                        jobId={jobId}
                        teamId={teamId}
                      />
                    </div>
                  )}
                  {jobId && teamId && (
                    <div>
                      <p className="text-[11px] font-semibold text-muted-foreground uppercase tracking-wider pb-2 border-b border-border/30 mb-3">
                        Your Evaluation
                      </p>
                      <ScorecardPanel
                        resumeId={r.resume_id}
                        jobId={jobId}
                        teamId={teamId}
                      />
                    </div>
                  )}

                  {/* Hire Outcome — show for hired/rejected candidates */}
                  {jobId && (currentStage === "hired" || currentStage === "rejected") && (
                    <div>
                      <p className="text-[11px] font-semibold text-muted-foreground uppercase tracking-wider pb-2 border-b border-border/30 mb-3">
                        Outcome
                      </p>
                      <HireOutcomeCard
                        resumeId={r.resume_id}
                        jobId={jobId}
                        currentScore={r.overall_score}
                      />
                    </div>
                  )}
                </div>
              </ScrollArea>
            </TabsContent>

            {/* ── History tab ───────────────────────────────────────────── */}
            <TabsContent value="history" className="flex-1 min-h-0 mt-0">
              <ScrollArea className="h-full">
                <div className="px-5 py-5 space-y-5">
                  {jobId && (
                    <InterviewsPanel
                      resumeId={r.resume_id}
                      jobId={jobId}
                      candidateName={candidateName}
                      candidateEmail={r.candidate_email}
                    />
                  )}
                </div>
              </ScrollArea>
            </TabsContent>
          </Tabs>
        </SheetContent>
      </Sheet>

      {/* ── Dialogs (outside Sheet to avoid stacking context issues) ──────── */}
      {r.candidate_email && (
        <EmailOutreachDialog
          open={emailDialogOpen}
          onOpenChange={setEmailDialogOpen}
          candidateName={candidateName}
          candidateEmail={r.candidate_email}
          jobTitle={jobTitle || "Open Position"}
          matchScore={Math.round(r.overall_score ?? 0)}
          resumeId={r.resume_id}
          jobId={jobId || ""}
        />
      )}

      {jobId && (
        <ScheduleInterviewDialog
          open={scheduleOpen}
          onOpenChange={setScheduleOpen}
          jobId={jobId}
          resumeId={r.resume_id}
          candidateName={candidateName}
          candidateEmail={r.candidate_email}
        />
      )}

      {jobId && (
        <RejectCandidateDialog
          open={rejectDialogOpen}
          onOpenChange={setRejectDialogOpen}
          result={r}
          jobTitle={jobTitle || "Open Position"}
          jobId={jobId}
          onStageChange={onStageChange}
        />
      )}

      {r.candidate_phone && (
        <WhatsAppOutreachDialog
          open={whatsappOpen}
          onOpenChange={setWhatsappOpen}
          candidateName={candidateName}
          candidatePhone={r.candidate_phone}
          jobTitle={jobTitle || "Open Position"}
          matchScore={Math.round(r.overall_score ?? 0)}
        />
      )}

      {duplicates && duplicates.length > 0 && (
        <DuplicateDialog
          open={duplicateDialogOpen}
          onOpenChange={setDuplicateDialogOpen}
          candidateName={candidateName}
          duplicates={duplicates}
        />
      )}
    </>
  );
};

export default CandidateDetailSheet;

