import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import type { ActivityItem } from "@/hooks/useActivityFeed";

export interface TasksByAssignee {
  user_id: string;
  pending: number;
  completed: number;
}

export interface RecruiterActivityRow {
  user_id: string;
  stage_moves: number;
  notes_authored: number;
  tasks_completed: number;
  activity_14d: number;
}

export interface TeamDashboardData {
  totalJobs: number;
  activeCandidates: number;
  pendingTasks: number;
  memberCount: number;
  recentActivity: ActivityItem[];
  tasksByAssignee: TasksByAssignee[];
  recruiterActivity: RecruiterActivityRow[];
}

export function useTeamDashboard(teamId: string | null) {
  return useQuery<TeamDashboardData>({
    queryKey: ["team-dashboard", teamId],
    queryFn: async () => {
      if (!teamId) {
        return {
          totalJobs: 0,
          activeCandidates: 0,
          pendingTasks: 0,
          memberCount: 0,
          recentActivity: [],
          tasksByAssignee: [],
          recruiterActivity: [],
        };
      }

      const [
        jobsRes,
        pendingTasksRes,
        membersRes,
        activityRes,
        allTasksRes,
      ] = await Promise.all([
        // Total jobs for this team
        (supabase as any)
          .from("jobs")
          .select("id", { count: "exact", head: true })
          .eq("team_id", teamId),

        // Pending tasks count
        (supabase as any)
          .from("tasks")
          .select("id", { count: "exact", head: true })
          .eq("team_id", teamId)
          .neq("status", "done"),

        // Team members count
        (supabase as any)
          .from("team_members")
          .select("id", { count: "exact", head: true })
          .eq("team_id", teamId),

        // Last 5 activity items
        (supabase as any)
          .from("activity_log")
          .select("*")
          .eq("team_id", teamId)
          .order("created_at", { ascending: false })
          .limit(5),

        // All tasks for assignee summary (limited columns)
        (supabase as any)
          .from("tasks")
          .select("assigned_to, status")
          .eq("team_id", teamId)
          .not("assigned_to", "is", null),
      ]);

      // Active candidates: count resumes linked to this team's jobs
      // We fetch job IDs first, then count resumes
      let activeCandidates = 0;
      const { data: jobIds } = await (supabase as any)
        .from("jobs")
        .select("id")
        .eq("team_id", teamId);

      const teamJobIds =
        (jobIds as { id: string }[] | null)?.map((j) => j.id) ?? [];

      if (teamJobIds.length > 0) {
        const { count } = await (supabase as any)
          .from("resumes")
          .select("id", { count: "exact", head: true })
          .in("job_id", teamJobIds);
        activeCandidates = count ?? 0;
      }

      // ── Recruiter Activity (last 14 days) ───────────────────────────
      // Four parallel aggregate queries — stage moves, notes, completed tasks, activity count
      const fourteenDaysAgo = new Date(
        Date.now() - 14 * 24 * 60 * 60 * 1000
      ).toISOString();

      const [stageMovesRes, notesRes, completedTasksRes, activity14dRes] =
        await Promise.all([
          teamJobIds.length
            ? (supabase as any)
                .from("stage_history")
                .select("changed_by")
                .in("job_id", teamJobIds)
                .gte("changed_at", fourteenDaysAgo)
                .not("changed_by", "is", null)
            : Promise.resolve({ data: [] }),
          teamJobIds.length
            ? (supabase as any)
                .from("candidate_notes")
                .select("author_id")
                .in("job_id", teamJobIds)
                .gte("created_at", fourteenDaysAgo)
                .not("author_id", "is", null)
            : Promise.resolve({ data: [] }),
          (supabase as any)
            .from("tasks")
            .select("assigned_to")
            .eq("team_id", teamId)
            .eq("status", "done")
            .gte("updated_at", fourteenDaysAgo)
            .not("assigned_to", "is", null),
          (supabase as any)
            .from("activity_log")
            .select("actor_id")
            .eq("team_id", teamId)
            .gte("created_at", fourteenDaysAgo)
            .not("actor_id", "is", null),
        ]);

      const recruiterMap = new Map<string, RecruiterActivityRow>();
      const ensureRow = (userId: string): RecruiterActivityRow => {
        let row = recruiterMap.get(userId);
        if (!row) {
          row = {
            user_id: userId,
            stage_moves: 0,
            notes_authored: 0,
            tasks_completed: 0,
            activity_14d: 0,
          };
          recruiterMap.set(userId, row);
        }
        return row;
      };

      ((stageMovesRes.data ?? []) as { changed_by: string }[]).forEach((r) => {
        if (r.changed_by) ensureRow(r.changed_by).stage_moves += 1;
      });
      ((notesRes.data ?? []) as { author_id: string }[]).forEach((r) => {
        if (r.author_id) ensureRow(r.author_id).notes_authored += 1;
      });
      ((completedTasksRes.data ?? []) as { assigned_to: string }[]).forEach(
        (r) => {
          if (r.assigned_to) ensureRow(r.assigned_to).tasks_completed += 1;
        }
      );
      ((activity14dRes.data ?? []) as { actor_id: string }[]).forEach((r) => {
        if (r.actor_id) ensureRow(r.actor_id).activity_14d += 1;
      });

      const recruiterActivity = Array.from(recruiterMap.values()).sort(
        (a, b) => b.activity_14d - a.activity_14d
      );

      // Build tasks-by-assignee summary
      const tasksByAssignee: TasksByAssignee[] = [];
      const allTasks = (allTasksRes.data ?? []) as { assigned_to: string; status: string }[];
      const assigneeMap = new Map<string, TasksByAssignee>();

      for (const t of allTasks) {
        if (!t.assigned_to) continue;
        if (!assigneeMap.has(t.assigned_to)) {
          assigneeMap.set(t.assigned_to, { user_id: t.assigned_to, pending: 0, completed: 0 });
        }
        const entry = assigneeMap.get(t.assigned_to)!;
        if (t.status === "done") {
          entry.completed += 1;
        } else {
          entry.pending += 1;
        }
      }
      assigneeMap.forEach((v) => tasksByAssignee.push(v));

      return {
        totalJobs: jobsRes.count ?? 0,
        activeCandidates,
        pendingTasks: pendingTasksRes.count ?? 0,
        memberCount: membersRes.count ?? 0,
        recentActivity: (activityRes.data ?? []) as ActivityItem[],
        tasksByAssignee,
      };
    },
    enabled: !!teamId,
    staleTime: 60_000,
  });
}

