import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";

// ─── Types ──────────────────────────────────────────────────────────────────

export type OutreachKind = "email" | "sms";
export type OutreachStatus = "sent" | "failed" | "pending";

export interface OutreachEvent {
  id: string;
  kind: OutreachKind;
  to: string;
  subject: string | null;
  body: string | null;
  status: OutreachStatus;
  sent_at: string;
  sender_user_id: string | null;
  error: string | null;
}

interface OutreachLogRow {
  id: string;
  type: string | null;
  to_address: string | null;
  subject: string | null;
  status: string | null;
  sent_at: string | null;
  user_id: string | null;
}

interface SmsLogRow {
  id: string;
  to_phone: string;
  message: string | null;
  status: string | null;
  created_at: string | null;
  user_id: string | null;
  error: string | null;
}

// ─── Normalizers ────────────────────────────────────────────────────────────

function normalizeStatus(raw: string | null | undefined): OutreachStatus {
  if (raw === "failed") return "failed";
  if (raw === "pending") return "pending";
  return "sent";
}

function fromOutreachLog(row: OutreachLogRow): OutreachEvent {
  return {
    id: `email:${row.id}`,
    kind: "email",
    to: row.to_address ?? "",
    subject: row.subject ?? null,
    body: null,
    status: normalizeStatus(row.status),
    sent_at: row.sent_at ?? new Date(0).toISOString(),
    sender_user_id: row.user_id ?? null,
    error: null,
  };
}

function fromSmsLog(row: SmsLogRow): OutreachEvent {
  return {
    id: `sms:${row.id}`,
    kind: "sms",
    to: row.to_phone,
    subject: null,
    body: row.message ?? null,
    status: normalizeStatus(row.status),
    sent_at: row.created_at ?? new Date(0).toISOString(),
    sender_user_id: row.user_id ?? null,
    error: row.error ?? null,
  };
}

// ─── Hook ────────────────────────────────────────────────────────────────────

/**
 * Fetches every outreach event for a candidate — emails (`outreach_log`)
 * and SMS (`sms_logs`) merged into a single timeline sorted by most recent.
 */
export function useOutreachHistory(resumeId: string | null) {
  return useQuery<OutreachEvent[]>({
    queryKey: ["outreach-history", resumeId],
    queryFn: async () => {
      if (!resumeId) return [];

      const [emailsRes, smsRes] = await Promise.all([
        (supabase as any)
          .from("outreach_log")
          .select("id, type, to_address, subject, status, sent_at, user_id")
          .eq("resume_id", resumeId)
          .order("sent_at", { ascending: false }),
        (supabase as any)
          .from("sms_logs")
          .select("id, to_phone, message, status, created_at, user_id, error")
          .eq("resume_id", resumeId)
          .order("created_at", { ascending: false }),
      ]);

      const emails = ((emailsRes.data ?? []) as OutreachLogRow[]).map(fromOutreachLog);
      const sms = ((smsRes.data ?? []) as SmsLogRow[]).map(fromSmsLog);

      const merged = [...emails, ...sms];
      merged.sort((a, b) => (a.sent_at < b.sent_at ? 1 : -1));
      return merged;
    },
    enabled: !!resumeId,
    staleTime: 60_000,
  });
}

