import { useMemo, useState } from "react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import { Mail, MessageSquare, CheckCircle2, XCircle, Clock, Inbox } from "lucide-react";
import { formatDistanceToNow, format } from "date-fns";
import { useOutreachHistory, type OutreachEvent, type OutreachKind } from "@/hooks/useOutreachHistory";

interface OutreachPanelProps {
  resumeId: string;
}

type FilterKind = "all" | OutreachKind;

// ─── Status badge ───────────────────────────────────────────────────────────

function StatusBadge({ status }: { status: OutreachEvent["status"] }) {
  if (status === "sent") {
    return (
      <Badge
        variant="outline"
        className="gap-1 text-xs h-5 bg-emerald-50 text-emerald-700 border-emerald-200 dark:bg-emerald-950/40 dark:text-emerald-400 dark:border-emerald-800/60"
      >
        <CheckCircle2 className="h-3 w-3" />
        Sent
      </Badge>
    );
  }
  if (status === "failed") {
    return (
      <Badge
        variant="outline"
        className="gap-1 text-xs h-5 bg-red-50 text-red-700 border-red-200 dark:bg-red-950/40 dark:text-red-400 dark:border-red-800/60"
      >
        <XCircle className="h-3 w-3" />
        Failed
      </Badge>
    );
  }
  return (
    <Badge
      variant="outline"
      className="gap-1 text-xs h-5 bg-amber-50 text-amber-700 border-amber-200 dark:bg-amber-950/40 dark:text-amber-400 dark:border-amber-800/60"
    >
      <Clock className="h-3 w-3" />
      Pending
    </Badge>
  );
}

// ─── Single event row ───────────────────────────────────────────────────────

function EventRow({ event }: { event: OutreachEvent }) {
  const Icon = event.kind === "email" ? Mail : MessageSquare;
  const iconBg =
    event.kind === "email"
      ? "bg-blue-50 text-blue-600 dark:bg-blue-950/40 dark:text-blue-400"
      : "bg-violet-50 text-violet-600 dark:bg-violet-950/40 dark:text-violet-400";

  const preview = event.kind === "email" ? event.subject ?? "(no subject)" : event.body ?? "";
  const relativeTime = (() => {
    try {
      return formatDistanceToNow(new Date(event.sent_at), { addSuffix: true });
    } catch {
      return "—";
    }
  })();
  const absoluteTime = (() => {
    try {
      return format(new Date(event.sent_at), "MMM d, yyyy 'at' h:mm a");
    } catch {
      return "";
    }
  })();

  return (
    <div className="flex items-start gap-3 px-4 py-3 hover:bg-muted/40 transition-colors">
      <div
        className={`h-8 w-8 rounded-lg flex items-center justify-center shrink-0 ${iconBg}`}
      >
        <Icon className="h-4 w-4" />
      </div>
      <div className="flex-1 min-w-0 space-y-1">
        <div className="flex items-center gap-2 flex-wrap">
          <span className="text-xs font-medium text-muted-foreground truncate">
            {event.to || "—"}
          </span>
          <StatusBadge status={event.status} />
        </div>
        <p className="text-sm text-foreground leading-snug line-clamp-2">{preview}</p>
        <p className="text-xs text-muted-foreground/70" title={absoluteTime}>
          {relativeTime}
        </p>
      </div>
    </div>
  );
}

// ─── Panel ──────────────────────────────────────────────────────────────────

const OutreachPanel = ({ resumeId }: OutreachPanelProps) => {
  const { data: events = [], isLoading } = useOutreachHistory(resumeId);
  const [filter, setFilter] = useState<FilterKind>("all");

  const counts = useMemo(() => {
    let emails = 0;
    let sms = 0;
    for (const e of events) {
      if (e.kind === "email") emails++;
      else sms++;
    }
    return { total: events.length, emails, sms };
  }, [events]);

  const filtered = useMemo(() => {
    if (filter === "all") return events;
    return events.filter((e) => e.kind === filter);
  }, [events, filter]);

  if (isLoading) {
    return (
      <div className="rounded-xl border border-border overflow-hidden">
        <div className="px-4 py-3 border-b border-border bg-muted/30">
          <Skeleton className="h-4 w-40" />
        </div>
        <div className="p-4 space-y-3">
          {[0, 1, 2].map((i) => (
            <div key={i} className="flex gap-3">
              <Skeleton className="h-8 w-8 rounded-lg" />
              <div className="flex-1 space-y-2">
                <Skeleton className="h-3 w-32" />
                <Skeleton className="h-4 w-full" />
                <Skeleton className="h-3 w-20" />
              </div>
            </div>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="rounded-xl border border-border overflow-hidden">
      {/* Header */}
      <div className="px-4 py-3 border-b border-border bg-muted/30 flex items-center justify-between gap-3 flex-wrap">
        <div className="flex items-center gap-2">
          <Inbox className="h-4 w-4 text-primary" />
          <h4 className="text-sm font-semibold text-foreground">Email &amp; SMS History</h4>
          {counts.total > 0 && (
            <Badge variant="secondary" className="text-xs h-5">
              {counts.total}
            </Badge>
          )}
        </div>
        {counts.total > 0 && (
          <div className="flex items-center gap-1">
            <Button
              size="sm"
              variant={filter === "all" ? "default" : "ghost"}
              className="h-6 px-2 text-xs"
              onClick={() => setFilter("all")}
            >
              All
            </Button>
            <Button
              size="sm"
              variant={filter === "email" ? "default" : "ghost"}
              className="h-6 px-2 text-xs gap-1"
              onClick={() => setFilter("email")}
              disabled={counts.emails === 0}
            >
              <Mail className="h-3 w-3" />
              {counts.emails}
            </Button>
            <Button
              size="sm"
              variant={filter === "sms" ? "default" : "ghost"}
              className="h-6 px-2 text-xs gap-1"
              onClick={() => setFilter("sms")}
              disabled={counts.sms === 0}
            >
              <MessageSquare className="h-3 w-3" />
              {counts.sms}
            </Button>
          </div>
        )}
      </div>

      {/* Body */}
      {filtered.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-10 space-y-2 text-center">
          <div className="rounded-xl bg-muted/50 p-3">
            <Inbox className="h-5 w-5 text-muted-foreground/50" />
          </div>
          <p className="text-sm font-medium text-foreground">
            {counts.total === 0 ? "No outreach yet" : "No matching events"}
          </p>
          <p className="text-xs text-muted-foreground max-w-xs">
            {counts.total === 0
              ? "Emails and SMS sent to this candidate will appear here."
              : "Try a different filter."}
          </p>
        </div>
      ) : (
        <div className="divide-y divide-border/60">
          {filtered.map((event) => (
            <EventRow key={event.id} event={event} />
          ))}
        </div>
      )}
    </div>
  );
};

export default OutreachPanel;

