// ─── Candidate Source Tracking ──────────────────────────────────────────────
// Shared constants for the `resumes.source` column.
// All values must match the DB default or be set explicitly on insert.
// ─────────────────────────────────────────────────────────────────────────────

export type CandidateSource =
  | "upload"       // default — manual file upload via JobDetailView
  | "email"        // email-ingest edge function
  | "career_page"  // public career page application (submit-application)
  | "api"          // REST API / Chrome extension / extension-capture
  | "linkedin"     // manually tagged as LinkedIn-sourced
  | "indeed"       // manually tagged
  | "naukri"       // manually tagged (India-first)
  | "referral"     // internal referral
  | "direct";      // direct inbound

export const SOURCE_LABELS: Record<CandidateSource, string> = {
  upload: "Manual upload",
  email: "Email",
  career_page: "Career page",
  api: "API",
  linkedin: "LinkedIn",
  indeed: "Indeed",
  naukri: "Naukri",
  referral: "Referral",
  direct: "Direct",
};

/**
 * Tailwind classes for the source badge — compact outline style with
 * a brand-color tint per source so recruiters can scan at a glance.
 */
export const SOURCE_BADGE_CLASSES: Record<CandidateSource, string> = {
  upload:
    "bg-muted text-muted-foreground border-border",
  email:
    "bg-blue-50 text-blue-700 border-blue-200 dark:bg-blue-950/40 dark:text-blue-400 dark:border-blue-800/60",
  career_page:
    "bg-emerald-50 text-emerald-700 border-emerald-200 dark:bg-emerald-950/40 dark:text-emerald-400 dark:border-emerald-800/60",
  api:
    "bg-violet-50 text-violet-700 border-violet-200 dark:bg-violet-950/40 dark:text-violet-400 dark:border-violet-800/60",
  linkedin:
    "bg-[#0A66C2]/10 text-[#0A66C2] border-[#0A66C2]/30 dark:text-[#60a5fa] dark:border-[#0A66C2]/40",
  indeed:
    "bg-[#2164F3]/10 text-[#2164F3] border-[#2164F3]/30 dark:text-[#60a5fa] dark:border-[#2164F3]/40",
  naukri:
    "bg-[#4A90D9]/10 text-[#4A90D9] border-[#4A90D9]/30 dark:text-[#60a5fa] dark:border-[#4A90D9]/40",
  referral:
    "bg-amber-50 text-amber-700 border-amber-200 dark:bg-amber-950/40 dark:text-amber-400 dark:border-amber-800/60",
  direct:
    "bg-rose-50 text-rose-700 border-rose-200 dark:bg-rose-950/40 dark:text-rose-400 dark:border-rose-800/60",
};

/**
 * Sources a user can pick manually when uploading candidates.
 * `email`, `career_page`, and `api` are set automatically by edge functions.
 */
export const MANUAL_SOURCE_OPTIONS: Array<{ value: CandidateSource; label: string }> = [
  { value: "upload", label: "Manual upload" },
  { value: "linkedin", label: "LinkedIn" },
  { value: "indeed", label: "Indeed" },
  { value: "naukri", label: "Naukri" },
  { value: "referral", label: "Referral" },
  { value: "direct", label: "Direct" },
];

/**
 * All valid sources, for the filter dropdown on the results page.
 */
export const ALL_SOURCE_OPTIONS: Array<{ value: CandidateSource; label: string }> = [
  { value: "upload", label: "Manual upload" },
  { value: "email", label: "Email" },
  { value: "career_page", label: "Career page" },
  { value: "api", label: "API" },
  { value: "linkedin", label: "LinkedIn" },
  { value: "indeed", label: "Indeed" },
  { value: "naukri", label: "Naukri" },
  { value: "referral", label: "Referral" },
  { value: "direct", label: "Direct" },
];

/**
 * Narrow an arbitrary string to a CandidateSource, defaulting to "upload".
 */
export function normalizeCandidateSource(raw: string | null | undefined): CandidateSource {
  if (!raw) return "upload";
  const valid: CandidateSource[] = [
    "upload",
    "email",
    "career_page",
    "api",
    "linkedin",
    "indeed",
    "naukri",
    "referral",
    "direct",
  ];
  return (valid as string[]).includes(raw) ? (raw as CandidateSource) : "upload";
}

/**
 * Whether to render a badge on candidate rows. `upload` is the silent default.
 */
export function shouldShowSourceBadge(source: string | null | undefined): boolean {
  const normalized = normalizeCandidateSource(source);
  return normalized !== "upload";
}

