                  .map((r) => ({
                    id: r.resume_id,
                    name: r.candidate_name || formatCandidateName(r.filename),
                    score: r.overall_score,
                    stage: stageMap.get(r.resume_id)?.stage ?? "applied",
                    email: (r as any).candidate_email ?? null,
                    tags: tagsForResume(r.resume_id),
                    assigneeEmail: (r as any).assigned_to
                      ? teamMembers.find((m) => m.user_id === (r as any).assigned_to)?.email ?? null
                      : null,
                  }))}
                onStageChange={(candidateId, newStage) =>
                  handleStageChange(candidateId, newStage as HiringStage)
                }
                stages={customPipelineStages.map((s) => s.name.toLowerCase())}
                stageConfig={Object.fromEntries(
                  customPipelineStages.map((s) => [s.name.toLowerCase(), { label: s.name, color: s.color }])
                )}
              />
            )}
          </div>
        )}

        {/* Distribute tab content */}
        {isExistingJob && isAuthenticated && activeTab === "distribute" && selectedJobId && selectedJob && (
          <JobDistributionPanel
            jobId={selectedJobId}
            jobTitle={selectedJob.title}
            slug={(selectedJob as any).slug ?? null}
            teamId={team?.id ?? null}
            careerPageActive={(selectedJob as any).is_published ?? false}
          />
        )}

        {/* CTA for unauthenticated only */}
        {!isExistingJob && allResults.length === 0 && !isAuthenticated && (
          <div className="rounded-lg border border-border bg-card px-6 py-5 flex items-center justify-between gap-4 flex-wrap">
            <div>
              <p className="text-sm font-semibold text-foreground">Sign up and rank your first batch free.</p>
              <p className="text-xs text-muted-foreground mt-0.5">No credit card. No setup. Results in under 2 minutes.</p>
            </div>
            <button
              onClick={onAuthRequired}
              className="inline-flex items-center gap-2 bg-primary text-primary-foreground text-sm font-semibold px-4 py-2 rounded-lg hover:bg-primary/90 transition-colors shrink-0"
            >
              Get started free <ArrowRight className="h-4 w-4" />
            </button>
          </div>
        )}

        {/* Resumes tab — ranking workflow, progress, results — hidden when Applications or Pipeline tab active */}
        {(!isExistingJob || !isAuthenticated || activeTab === "resumes") && <>

        {/* Analyzing JD indicator */}
        {analyzingJd && (
          <div className="flex items-center gap-2 text-sm text-primary font-medium animate-fade-in">
            <Loader2 className="h-4 w-4 animate-spin" />
            Analyzing job description…
          </div>
        )}

        {/* Status & Progress */}
        <div className="space-y-3">
          {validationErrors.length > 0 && (
            <div className="text-sm text-destructive space-y-1">
              {validationErrors.map((err, i) => <p key={i}>• {err}</p>)}
            </div>
          )}
          {rankingError && (
            <div className={`rounded-lg border p-4 flex items-start gap-3 animate-fade-in ${
              rankingError.type === "credits" ? "border-destructive/40 bg-destructive/5" : "border-border bg-muted/50"
            }`}>
              <AlertTriangle className={`h-5 w-5 mt-0.5 shrink-0 ${rankingError.type === "credits" ? "text-destructive" : "text-muted-foreground"}`} />
              <div className="flex-1">
                <p className="text-sm font-medium">
                  {rankingError.type === "credits" ? "Not enough credits" : rankingError.type === "rate_limit" ? "Too many requests" : "Ranking failed"}
                </p>
                <p className="text-sm text-muted-foreground mt-0.5">{rankingError.message}</p>
                {rankingError.type === "credits" && (
                  <Button variant="outline" size="sm" className="mt-2 gap-1.5" asChild>
                    <Link to="/billing"><Wallet className="h-3.5 w-3.5" /> Buy Credits</Link>
                  </Button>
                )}
              </div>
            </div>
          )}
          {stuckJobDetected && (
            <div className="rounded-lg border border-amber-500/40 bg-amber-500/5 p-4 flex items-start gap-3 animate-fade-in">
              <AlertTriangle className="h-5 w-5 mt-0.5 shrink-0 text-amber-500" />
              <div className="flex-1">
                <p className="text-sm font-medium">Ranking appears stuck</p>
                <p className="text-sm text-muted-foreground mt-0.5">
                  Processing has been running for over 5 minutes. Some resumes may not have been scored.
                </p>
                <Button
                  size="sm"
                  variant="outline"
                  className="mt-2"
                  onClick={handleRetryStuck}
                  disabled={retrying}
                >
                  {retrying ? <Loader2 className="h-3 w-3 animate-spin mr-1" /> : <RefreshCw className="h-3 w-3 mr-1" />}
                  Retry unscored resumes
                </Button>
              </div>
            </div>
          )}
          {ranking && (
            <div className="space-y-2 animate-fade-in">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2 text-sm text-primary font-medium">
                  <Loader2 className="h-4 w-4 animate-spin" />
                  {rankingProgress < 25 ? "Analyzing job…" : rankingProgress < 40 ? "Preparing resumes…" : rankingProgress < 60 ? "Parsing resumes…" : totalToScore > 0 ? `Scoring ${scoredCount}/${totalToScore}…` : "Scoring candidates…"}
                </div>
              </div>
              <Progress value={rankingProgress} className="h-2" aria-label={`Ranking progress: ${Math.round(rankingProgress)}%`} />
            </div>
          )}
        </div>


        {/* Rediscovery banner — shows past candidates that match this job */}
        {isExistingJob && isAuthenticated && selectedJobId && !rediscoveryDismissed && (
          <RediscoveryBanner
            jobId={selectedJobId}
            onViewCandidates={() => setRediscoveryOpen(true)}
            onDismiss={() => setRediscoveryDismissed(true)}
          />
        )}

        {/* Rediscovery dialog — full list with import controls */}
        {isExistingJob && isAuthenticated && selectedJobId && (
          <RediscoveryDialog
            open={rediscoveryOpen}
            onOpenChange={setRediscoveryOpen}
            jobId={selectedJobId}
            existingResumeIds={new Set(existingResumes.map((r) => r.id))}
          />
        )}

        {/* Pending resumes banner — prompt to rank */}
        {isExistingJob && visibleResults.some(r => r.pending) && !ranking && (() => {
          const pendingCount = visibleResults.filter(r => r.pending).length;
          return (
            <Card className="border-primary/30 bg-primary/5">
              <CardContent className="px-5 py-4 flex items-center justify-between gap-4">
                <div>
                  <p className="text-sm font-medium text-foreground">
                    {pendingCount} new resume{pendingCount !== 1 ? "s" : ""} ready to rank
                  </p>
                  <p className="text-xs text-muted-foreground mt-0.5">
                    Score and rank {pendingCount === 1 ? "this candidate" : "these candidates"} against your job description.
                  </p>
                </div>
                <Button onClick={handleRerank} className="gap-1.5 shrink-0">
                  <Zap className="h-4 w-4" /> Rank {pendingCount}
                </Button>
              </CardContent>
            </Card>
          );
        })()}

        {/* Results Table */}
        {visibleResults.length > 0 && (
          <div ref={resultsRef}>
            <Card>
              <CardHeader className="px-4 py-3 space-y-3">
                {/* Row 1: Title + stage filters */}
                <div className="flex items-center gap-2 flex-wrap">
                  <CardTitle className="text-sm font-semibold">
                    Results ({visibleResults.filter(r => !r.pending).length}{visibleResults.some(r => r.pending) ? ` scored · ${visibleResults.filter(r => r.pending).length} pending` : ""})
                  </CardTitle>
                  {nonArchivedResults.some(r => !r.pending) && (
                    <div className="flex items-center gap-1 flex-wrap">
                      {allStageKeys.map((stage) => {
                        const count = effectiveStageCounts[stage] ?? 0;
                        if (count === 0) return null;
                        const isActive = stageFilter === stage;
                        // Use custom color from pipeline config when available
                        const customStage = customPipelineStages.find((s) => s.name.toLowerCase() === stage);
                        const activeClass = isActive ? "ring-1 ring-inset ring-current opacity-100" : "opacity-80 hover:opacity-100";
                        const stageLabel = customStage?.name ?? (stage.charAt(0).toUpperCase() + stage.slice(1));
                        return (
                          <button
                            key={stage}
                            onClick={() => setStageFilter(isActive ? null : stage)}
                            className={`text-[11px] font-medium px-1.5 py-0.5 rounded transition-colors bg-muted text-muted-foreground hover:bg-muted-foreground/20 ${activeClass}`}
                          >
                            {count} {stageLabel}
                            {isActive && " ×"}
                          </button>
                        );
                      })}
                    </div>
                  )}
                  <div className="flex items-center gap-1.5 ml-auto">
                    {/* AI Candidate Search */}
                    {isAuthenticated && selectedJobId && (
                      <AICandidateSearch
                        jobId={selectedJobId}
                        onSelectCandidate={(resumeId) => {
                          const match = allResults.find((r) => r.resume_id === resumeId);
                          if (match) setSelectedCandidateId(match.id);
                        }}
                      />
                    )}
                    {/* Blind Mode Toggle */}
                    {visibleResults.length > 0 && (
                      <Button
                        variant={blindMode ? "secondary" : "outline"}
                        size="sm"
                        className="h-7 gap-1.5 text-xs"
                        onClick={() => setBlindMode((v) => !v)}
                        title="Blind Mode hides candidate names and contact info to reduce bias"
                      >
                        <ScanLine className="h-3 w-3" />
                        {blindMode ? "Blind On" : "Blind"}
                      </Button>
                    )}
                    {dismissedResumes.size > 0 && (
                      <Button
                        variant={showArchived ? "secondary" : "outline"}
                        size="sm"
                        className="h-7 gap-1.5 text-xs"
                        onClick={() => setShowArchived((v) => !v)}
                      >
                        <FolderOpen className="h-3 w-3" />
                        Archived ({dismissedResumes.size})
                      </Button>
                    )}
                    {visibleResults.length > 0 && (
                      <Button
                        variant="outline"
                        size="sm"
                        className="h-7 gap-1.5 text-xs"
                        onClick={() => {
                          const formatCandidateNameLocal = (filename: string) => {
                            const name = filename.replace(/\.\w+$/, "");
                            if (UUID_REGEX.test(name)) return "Candidate";
                            return name.replace(/[-_]/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
                          };
                          const rows = visibleResults.filter((r) => !r.pending).map((r, i) => {
                            const matched = Array.isArray(r.matched_must_haves) ? r.matched_must_haves.length : 0;
                            const missing = Array.isArray(r.missing_must_haves) ? r.missing_must_haves.length : 0;
                            const total = matched + missing;
                            const jdAlignment = total > 0 ? Math.round((matched / total) * 100) : 0;
                            const stage = stageMap.get(r.resume_id)?.stage ?? "applied";
                            return {
                              "Rank": i + 1,
                              "Candidate Name": r.candidate_name || formatCandidateNameLocal(r.filename),
                              "Email": r.candidate_email ?? "",
                              "Phone": r.candidate_phone ?? "",
                              "Location": r.candidate_location ?? "",
                              "Stage": stage.charAt(0).toUpperCase() + stage.slice(1),
                              "Overall Score": r.overall_score?.toFixed(0) ?? "0",
                              "Confidence": (r.confidence ?? 0).toFixed(0),
                              "Hard Fit": r.hard_fit ? "Yes" : "No",
                              "JD Alignment %": jdAlignment,
                              "Strengths": (r.strengths_json ?? []).join("; "),
                              "Gaps": (r.gaps_json ?? []).join("; "),
                              "Missing Skills": (r.missing_skills ?? []).join("; "),
                            };
                          });
                          exportToCSV(rows, selectedJob?.title || "results");
                        }}
                      >
                        <FileSpreadsheet className="h-3 w-3" />
                        Export
                      </Button>
                    )}
                    {isExistingJob && existingResumes.length > 0 && (() => {
                      const hasPending = visibleResults.some(r => r.pending);
                      const hasScored = visibleResults.some(r => !r.pending);
                      return (
                        <Button
                          variant={hasPending && !hasScored ? "default" : "outline"}
                          size="sm"
                          className="h-7 gap-1.5 text-xs"
                          disabled={ranking}
                          onClick={handleRerank}
                        >
                          {ranking ? <Loader2 className="h-3 w-3 animate-spin" /> : hasPending && !hasScored ? <Zap className="h-3 w-3" /> : <RefreshCw className="h-3 w-3" />}
                          {hasPending && !hasScored ? `Rank ${visibleResults.filter(r => r.pending).length} Resumes` : "Re-rank"}
                        </Button>
                      );
                    })()}
                  </div>
                </div>

                {/* Row 2: Selection actions — only when candidates are selected */}
                {selectedResumes.size > 0 && (
                  <div className="flex items-center gap-2 px-3 py-2 rounded-lg bg-muted/50 border border-border">
                    <span className="text-xs font-medium text-foreground">{selectedResumes.size} selected</span>
                    <div className="flex items-center gap-1.5 ml-auto">
                      <Button variant="outline" size="sm" className="h-7 text-xs" onClick={() => setSelectedResumes(new Set())}>
                        Clear
                      </Button>
                      {/* ── Add to Sequence (email drip campaigns) ─────────────────────── */}
                      <Button
                        variant="outline"
                        size="sm"
                        className="h-7 gap-1.5 text-xs"
                        onClick={() => setEnrollDialogOpen(true)}
                      >
                        <Mail className="h-3 w-3" />
                        Add to Sequence
                      </Button>
                      <Button variant="destructive" size="sm" className="h-7 gap-1.5 text-xs" onClick={() => setDeleteConfirm({ type: "bulk" })}>
                        <Trash2 className="h-3 w-3" /> Delete
                      </Button>
                    </div>
                  </div>
                )}
                {/* EnrollInSequenceDialog — rendered outside the button row to avoid layout issues */}
                {selectedJobId && (
                  <EnrollInSequenceDialog
                    open={enrollDialogOpen}
                    onOpenChange={setEnrollDialogOpen}
                    selectedResumeIds={Array.from(selectedResumes)}
                    jobId={selectedJobId}
                  />
                )}
              </CardHeader>
              <CardContent className="p-0">
                <div className="overflow-x-auto">
                  <Table>
                    <TableHeader className="sticky top-0 bg-card z-10">
                      <TableRow>
                        <TableHead className="w-10">
                          <Checkbox
                            aria-label="Select all candidates"
                            checked={visibleResults.length > 0 && visibleResults.every(r => selectedResumes.has(r.resume_id))}
                            onCheckedChange={(checked) => {
                              if (checked) setSelectedResumes(prev => new Set([...prev, ...visibleResults.map(r => r.resume_id)]));
                              else setSelectedResumes(prev => { const next = new Set(prev); visibleResults.forEach(r => next.delete(r.resume_id)); return next; });
                            }}
                          />
                        </TableHead>
                        <TableHead className="w-14 text-center">#</TableHead>
                        <TableHead>Candidate</TableHead>
                        <TableHead className="w-32">Match</TableHead>
                        <TableHead className="w-20">Strength</TableHead>
                        <TableHead className="w-36"></TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {ranking && visibleResults.filter(r => !r.pending).length === 0 && (
                        <>
                          {[0, 1, 2, 3, 4].map((i) => (
                            <TableRow key={`skel-${i}`} className="animate-pulse">
                              <TableCell><Skeleton className="h-4 w-4 rounded" /></TableCell>
                              <TableCell className="text-center"><Skeleton className="h-4 w-6 mx-auto rounded" /></TableCell>
                              <TableCell><Skeleton className="h-4 w-40" /></TableCell>
                              <TableCell><Skeleton className="h-4 w-24" /></TableCell>
                              <TableCell><Skeleton className="h-5 w-16 rounded-full" /></TableCell>
                              <TableCell><Skeleton className="h-4 w-20" /></TableCell>
                            </TableRow>
                          ))}
                        </>
                      )}
                      {visibleResults.map((r, index) => (
                        <CandidateRow
                          key={r.id}
                          result={r}
                          index={index}
                          isSelected={selectedResumes.has(r.resume_id)}
                          isActive={selectedCandidateId === r.id}
                          jobId={selectedJobId}
                          jobTitle={selectedJob?.title}
                          onSelect={selectCandidate}
                          onToggleSelect={toggleSelectResume}
                          onDownload={downloadResume}
                          onDismiss={handleDismiss}
                          formatCandidateName={formatCandidateName}
                          currentStage={stageMap.get(r.resume_id)?.stage}
                          isDuplicate={duplicateResumeIds.has(r.resume_id)}
                          tags={tagsForResume(r.resume_id)}
                          assigneeEmail={
                            (r as any).assigned_to
                              ? teamMembers.find((m) => m.user_id === (r as any).assigned_to)?.email ?? null
                              : null
                          }
                          blindMode={blindMode}
                          authenticityData={(r as any).authenticity_json ?? null}
                        />
                      ))}
                    </TableBody>
                  </Table>
                </div>
              </CardContent>
            </Card>

            {/* Archived Candidates Panel */}
            {showArchived && archivedResults.length > 0 && (
              <Card className="mt-3 border-amber-200 dark:border-amber-800">
                <CardHeader className="pb-3">
                  <div className="flex items-center justify-between">
                    <CardTitle className="text-base flex items-center gap-2 text-amber-700 dark:text-amber-400">
                      <Archive className="h-4 w-4" />
                      Archived Candidates ({archivedResults.length})
                    </CardTitle>
                    <button
                      onClick={() => setShowArchived(false)}
                      className="text-muted-foreground hover:text-foreground"
                    >
                      <X className="h-4 w-4" />
                    </button>
                  </div>
                </CardHeader>
                <CardContent className="p-0">
                  <div className="overflow-x-auto">
                    <Table>
                      <TableHeader>
                        <TableRow>
                          <TableHead className="w-14 text-center pl-4">#</TableHead>
                          <TableHead>Candidate</TableHead>
                          <TableHead className="w-32">Match</TableHead>
                          <TableHead className="w-20">Strength</TableHead>
                          <TableHead className="w-20 text-right pr-4">Restore</TableHead>
                        </TableRow>
                      </TableHeader>
                      <TableBody>
                        {archivedResults.map((r, index) => {
                          const scoreColor = r.overall_score >= 70 ? "text-score-skills" : r.overall_score >= 40 ? "text-warning" : "text-destructive";
                          const strengthLabel = r.overall_score >= 70 ? "Strong" : r.overall_score >= 40 ? "Good" : "Weak";
                          const strengthVariant = r.overall_score >= 70 ? "success" : r.overall_score >= 40 ? "warning" : "destructive";
                          return (
                            <TableRow key={r.id} className="opacity-60 hover:opacity-100 transition-opacity">
                              <TableCell className="text-center text-sm text-muted-foreground pl-4">{index + 1}</TableCell>
                              <TableCell className="font-medium text-sm">
                                {r.candidate_name || formatCandidateName(r.filename)}
                              </TableCell>
                              <TableCell>
                                {!r.pending && (
                                  <div className="flex items-center gap-2">
                                    <div className="flex-1 h-2 rounded-full bg-secondary overflow-hidden max-w-[80px]">
                                      <div
                                        className={`h-full rounded-full transition-all ${r.overall_score >= 70 ? "bg-score-skills" : r.overall_score >= 40 ? "bg-warning" : "bg-destructive"}`}
                                        style={{ width: `${Math.min(r.overall_score, 100)}%` }}
                                      />
                                    </div>
                                    <span className={`text-sm font-semibold tabular-nums ${scoreColor}`}>{r.overall_score?.toFixed(0)}%</span>
                                  </div>
                                )}
                              </TableCell>
                              <TableCell>
                                {!r.pending && <Badge variant={strengthVariant as "success" | "warning" | "destructive"} className="text-[11px]">{strengthLabel}</Badge>}
                              </TableCell>
                              <TableCell className="text-right pr-4">
                                <Button
                                  variant="ghost"
                                  size="icon"
                                  className="h-7 w-7 text-muted-foreground hover:text-amber-600"
                                  onClick={() => handleUnarchive(r.resume_id)}
                                  title="Restore candidate"
                                >
                                  <ArchiveRestore className="h-3.5 w-3.5" />
                                </Button>
                              </TableCell>
                            </TableRow>
                          );
                        })}
                      </TableBody>
                    </Table>
                  </div>
                </CardContent>
              </Card>
            )}
          </div>
        )}

        </> /* end Resumes tab content */}
      </div>

      {/* Delete Confirmation */}
      <AlertDialog open={!!deleteConfirm} onOpenChange={(open) => !open && setDeleteConfirm(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete {deleteCount} resume{deleteCount > 1 ? "s" : ""}?</AlertDialogTitle>
            <AlertDialogDescription>
              This will permanently delete {deleteCount} resume{deleteCount > 1 ? "s" : ""} and any associated results. This action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={deleting}>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={handleDeleteConfirm} disabled={deleting} className="bg-destructive text-destructive-foreground hover:bg-destructive/90">
              {deleting ? <Loader2 className="h-4 w-4 animate-spin mr-2" /> : null}
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* Confirm Edit JD Warning */}
      <AlertDialog open={confirmEditJdOpen} onOpenChange={setConfirmEditJdOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Edit Job Description?</AlertDialogTitle>
            <AlertDialogDescription className="space-y-2">
              <span className="block">
                This job has <strong>{results.length} ranked candidate{results.length !== 1 ? "s" : ""}</strong>. Editing the JD will make existing scores outdated since they were based on the original description.
              </span>
              <span className="block">
                You can re-rank resumes after editing. Standard credit charges will apply for re-ranking.
              </span>
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={() => setEditingJd(true)}>
              Edit Anyway
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* Guest Link Dialog */}
      {showGuestLink && selectedJobId && team?.id && (
        <GuestLinkDialog
          open={showGuestLink}
          onOpenChange={setShowGuestLink}
          jobId={selectedJobId}
          teamId={team.id}
        />
      )}

      {/* JD Generator Dialog */}
      {jdGeneratorOpen && (
        <JDGeneratorDialog
          open={jdGeneratorOpen}
          onOpenChange={setJdGeneratorOpen}
          onGenerated={(jd) => {
            setJobDescription(jd);
            toast.success("Generated JD applied");
          }}
        />
      )}


      {/* JD Rewrite Dialog */}
      {jdRewriteOpen && (
        <JDRewriteDialog
          open={jdRewriteOpen}
          onOpenChange={setJdRewriteOpen}
          jobId={isExistingJob ? selectedJobId! : ""}
          originalJd={isExistingJob ? (selectedJob?.job_description ?? "") : jobDescription}
          onApply={async (newJd) => {
            setJobDescription(newJd);
            if (isExistingJob && selectedJobId) {
              try {
                await supabase.from("jobs").update({ job_description: newJd }).eq("id", selectedJobId);
                onJobUpdated?.(selectedJobId, { job_description: newJd });
                toast.success("Job description updated");
              } catch (err) {
                toast.error("Failed to save rewritten JD");
              }
            }
          }}
        />
      )}

      {/* Candidate Detail Sheet */}
      {(() => {
        const selectedResult = selectedCandidateId ? visibleResults.find((r) => r.id === selectedCandidateId) ?? null : null;
        return (
          <CandidateDetailSheet
            result={selectedResult}
            isOpen={!!selectedCandidateId && !!selectedResult}
            onClose={() => setSelectedCandidateId(null)}
            jobId={selectedJobId}
            jobTitle={selectedJob?.title}
            teamId={team?.id ?? null}
            formatCandidateName={formatCandidateName}
            onDownload={downloadResume}
            onDismiss={handleDismiss}
            currentStage={selectedResult ? stageMap.get(selectedResult.resume_id)?.stage : undefined}
            stageUpdatedAt={selectedResult ? stageMap.get(selectedResult.resume_id)?.updated_at : undefined}
            onStageChange={handleStageChange}
            tags={selectedResult ? tagsForResume(selectedResult.resume_id) : []}
            teamMembers={teamMembers}
            onAddTag={addTag}
            onRemoveTag={removeTag}
            blindMode={blindMode}
            onAssigned={(_resumeId, _userId) => {
              // Refresh results to pick up new assigned_to value
              if (selectedJobId) {
                queryClient.invalidateQueries({ queryKey: ["resumes", selectedJobId] });
              }
            }}
          />
        );
      })()}
    </div>
  );
};

export default JobDetailView;

