                          <SelectValue placeholder="All sources" />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="all">All sources</SelectItem>
                          {Array.from(sourceCounts.entries()).map(([src, count]) => (
                            <SelectItem key={src} value={src}>
